_font_cache = {}


def font(name, size):
    """Load a font from the embedded base64 data (cached after first use).
    Falls back to PIL's built-in default font instead of crashing if, for
    any reason, decoding fails."""
    cache_key = (name, size)
    if cache_key in _font_cache:
        return _font_cache[cache_key]

    try:
        raw = base64.b64decode(_EMBEDDED_FONTS_B64[name])
        f = ImageFont.truetype(io.BytesIO(raw), size)
    except Exception:
        logging.getLogger(__name__).warning(
            "Could not load embedded font '%s' — falling back to PIL's default font.", name
        )
        try:
            f = ImageFont.load_default(size=size)
        except TypeError:
            f = ImageFont.load_default()

    _font_cache[cache_key] = f
    return f

f_title      = font("Poppins-Bold.ttf", 30)
f_display    = font("Poppins-Bold.ttf", 46)
f_label      = font("Poppins-Medium.ttf", 20)
f_username   = font("Poppins-Regular.ttf", 30)
f_stat_num   = font("Poppins-Bold.ttf", 40)
f_stat_label = font("Poppins-Medium.ttf", 18)
f_footer     = font("Poppins-Regular.ttf", 20)
f_footer_b   = font("Poppins-Bold.ttf", 20)

# ---------------------------------------------------------------------------
# Background: deep navy -> indigo diagonal gradient with soft glow accents
# ---------------------------------------------------------------------------
def make_background():
    top = (10, 14, 28)
    bottom = (20, 16, 46)
    bg = Image.new("RGB", (W, H), top)
    px = bg.load()
    for y in range(H):
        t = y / H
        r = int(top[0] + (bottom[0] - top[0]) * t)
        g = int(top[1] + (bottom[1] - top[1]) * t)
        b = int(top[2] + (bottom[2] - top[2]) * t)
        for x in range(W):
            px[x, y] = (r, g, b)

    # soft glow blobs (accent cyan + violet)
    glow = Image.new("RGB", (W, H), (0, 0, 0))
    gd = ImageDraw.Draw(glow)
    gd.ellipse([W-520, -260, W+260, 420], fill=(35, 140, 200))
    gd.ellipse([-260, H-420, 380, H+260], fill=(110, 60, 200))
    glow = glow.filter(ImageFilter.GaussianBlur(180))
    bg = Image.blend(bg, glow, 0.55)

    # subtle diagonal line texture
    tex = Image.new("L", (W, H), 0)
    td = ImageDraw.Draw(tex)
    for i in range(-H, W, 26):
        td.line([(i, 0), (i + H, H)], fill=10, width=1)
    tex = tex.filter(ImageFilter.GaussianBlur(0.3))
    overlay = Image.new("RGB", (W, H), (255, 255, 255))
    bg = Image.composite(overlay, bg, tex.point(lambda p: min(p, 14)))
    return bg


def rounded_rect(draw, box, radius, fill=None, outline=None, width=1):
    draw.rounded_rectangle(box, radius=radius, fill=fill, outline=outline, width=width)


def glass_panel(base, box, radius=26, fill=(255, 255, 255, 18), outline=(255, 255, 255, 40)):
    x0, y0, x1, y1 = box
    panel = Image.new("RGBA", (x1 - x0, y1 - y0), (0, 0, 0, 0))
    pd = ImageDraw.Draw(panel)
    pd.rounded_rectangle([0, 0, x1 - x0, y1 - y0], radius=radius, fill=fill, outline=outline, width=1)
    base.alpha_composite(panel, (x0, y0))


def circle_avatar(avatar_img, size, ring_color=(90, 210, 255), ring_width=6):
    avatar_img = ImageOps.fit(avatar_img.convert("RGB"), (size, size), Image.LANCZOS)
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse([0, 0, size, size], fill=255)
    out = Image.new("RGBA", (size + ring_width * 4, size + ring_width * 4), (0, 0, 0, 0))
    od = ImageDraw.Draw(out)
    cx = out.width // 2
    # outer soft ring glow
    od.ellipse([2, 2, out.width - 2, out.height - 2], outline=ring_color + (120,), width=ring_width + 8)
    od.ellipse([ring_width, ring_width, out.width - ring_width, out.height - ring_width],
               outline=ring_color + (255,), width=ring_width)
    out.paste(avatar_img, (ring_width * 2, ring_width * 2), mask)
    return out


def text_with_shadow(draw, pos, text, fnt, fill, shadow=(0, 0, 0, 120), offset=(0, 2)):
    x, y = pos
    draw.text((x + offset[0], y + offset[1]), text, font=fnt, fill=shadow)
    draw.text((x, y), text, font=fnt, fill=fill)


# ---------------------------------------------------------------------------
# Card design — "Universing" web theme: black background, thin glowing
# red/white geometric web-line accents from a corner, red as the featured
# accent, gold kept for medal ranks (universal convention). Inspired by
# user-provided reference images; deliberately NOT tracing any trademarked
# logo shape — the web pattern here is a plain geometric radial/concentric
# construction, not a copy of any specific artwork.
#
# Semi-transparent shapes are composited via a separate RGBA layer (glass(),
# draw_progress_ring()) rather than drawn directly on `bg`, because a
# low-alpha fill drawn straight onto an RGBA canvas doesn't blend — it just
# gets flattened to its opaque RGB value once the image is saved as RGB.
# ---------------------------------------------------------------------------
BG          = (5, 4, 6)
RED         = (232, 48, 58)
RED_DIM     = (140, 32, 40)
GOLD        = (255, 199, 92)
CARD_WHITE  = (240, 240, 244)
CARD_MUTED  = (150, 150, 160)
PANEL_FILL  = (255, 255, 255, 10)
PANEL_LINE  = (232, 48, 58, 70)

f_kicker   = font("Poppins-Medium.ttf", 20)
f_title2   = font("Poppins-Bold.ttf", 44)
f_sub      = font("Poppins-Regular.ttf", 22)
f_big      = font("Poppins-Bold.ttf", 46)
f_num_lg   = font("Poppins-Bold.ttf", 52)
f_label2   = font("Poppins-Medium.ttf", 17)
f_footer2  = font("Poppins-Regular.ttf", 19)
f_footer2b = font("Poppins-Bold.ttf", 19)
f_rank_num = font("Poppins-Bold.ttf", 30)

# ---------------------------------------------------------------------------
# Font-coverage-based name fallback. Built from the embedded Poppins font's
# REAL cmap table (fontTools), verified empirically against actual garbled
# names reported in production — Devanagari renders fine in this font,
# Bengali and emoji do not. Rather than guess Unicode-block ranges, this
# checks the exact glyph set the font can actually draw, and swaps to the
# (always-ASCII) @username whenever the display name would render as tofu
# boxes, instead of ever showing a name half-broken.
# ---------------------------------------------------------------------------
from fontTools.ttLib import TTFont as _TTFont

def _load_covered_codepoints():
    try:
        raw = base64.b64decode("".join(_EMBEDDED_FONTS_B64["Poppins-Regular.ttf"]))
        return frozenset(_TTFont(io.BytesIO(raw)).getBestCmap().keys())
    except Exception:
        return frozenset()

_COVERED_CODEPOINTS = _load_covered_codepoints()


def _renderable(text: str) -> bool:
    if not _COVERED_CODEPOINTS:
        return True  # fail open if cmap loading ever breaks — never crash a card over this
    return all(ord(ch) in _COVERED_CODEPOINTS for ch in text if not ch.isspace())


def display_identity(full_name: str, username: str, user_id, max_name_len: int = 20):
    """Returns (primary, secondary) strings for showing a member's identity
    on a card. Always prefers to show both name and @username together so
    there's an ASCII-safe fallback visible even when the name renders fine.
    If the name contains any character missing from the embedded font, it's
    dropped entirely (never shown half-broken) and the username, or a plain
    'Member <id>' placeholder, carries the identity instead."""
    name = (full_name or "").strip()
    uname = f"@{username}" if username else ""

    name_ok = bool(name) and _renderable(name)
    if len(name) > max_name_len:
        name = name[: max_name_len - 1] + "…"

    if name_ok and uname:
        return name, uname
    if name_ok and not uname:
        return name, ""
    if not name_ok and uname:
        return uname, ""
    return f"Member {user_id}", ""


def text_c(draw, cx, y, text, fnt, fill, shadow=(0, 0, 0, 160)):
    """Centered text at horizontal position cx, with a soft shadow."""
    bbox = draw.textbbox((0, 0), text, font=fnt)
    w = bbox[2] - bbox[0]
    x = cx - w / 2
    draw.text((x + 1, y + 2), text, font=fnt, fill=shadow)
    draw.text((x, y), text, font=fnt, fill=fill)
    return w


def glass(base, box, radius=24, fill=PANEL_FILL, outline=PANEL_LINE, width=1):
    x0, y0, x1, y1 = box
    panel = Image.new("RGBA", (int(x1 - x0), int(y1 - y0)), (0, 0, 0, 0))
    pd = ImageDraw.Draw(panel)
    pd.rounded_rectangle([0, 0, x1 - x0, y1 - y0], radius=radius, fill=fill, outline=outline, width=width)
    base.alpha_composite(panel, (int(x0), int(y0)))


def _draw_web(draw, cx, cy, max_r, rings=5, spokes=10, color=(232, 48, 58, 26), width=1):
    """A thin-line radial web pattern — geometric spiderweb motif built from
    plain trigonometry, not a traced logo or artwork."""
    for i in range(spokes):
        ang = (2 * math.pi / spokes) * i - math.pi / 2
        x, y = cx + max_r * math.cos(ang), cy + max_r * math.sin(ang)
        draw.line([(cx, cy), (x, y)], fill=color, width=width)
    for ring in range(1, rings + 1):
        r = max_r * ring / rings
        pts = []
        for i in range(spokes):
            ang = (2 * math.pi / spokes) * i - math.pi / 2
            pts.append((cx + r * math.cos(ang), cy + r * math.sin(ang)))
        pts.append(pts[0])
        draw.line(pts, fill=color, width=width, joint="curve")


def make_background_web(rng_seed=1, web_corner="tr"):
    """Pure black canvas with a faint thin-line web radiating from one
    corner, plus sparse embers."""
    rng = random.Random(rng_seed)
    bg = Image.new("RGBA", (W, H), BG + (255,))
    draw = ImageDraw.Draw(bg)

    corners = {"tr": (W + 60, -60), "tl": (-60, -60), "br": (W + 60, H + 60), "bl": (-60, H + 60)}
    cx, cy = corners[web_corner]
    _draw_web(draw, cx, cy, max_r=620, rings=7, spokes=14, color=RED + (22,), width=1)

    ocx, ocy = corners["bl"] if web_corner in ("tr", "tl") else corners["tl"]
    _draw_web(draw, ocx, ocy, max_r=360, rings=5, spokes=10, color=(255, 255, 255, 10), width=1)

    embers = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    ed = ImageDraw.Draw(embers)
    for _ in range(70):
        x, y = rng.randint(0, W), rng.randint(0, H)
        r = rng.choice([0, 0, 1, 1, 2])
        a = rng.randint(40, 140)
        color = RED + (a,) if rng.random() < 0.35 else (255, 255, 255, a)
        ed.ellipse([x - r, y - r, x + r, y + r], fill=color)
    bg = Image.alpha_composite(bg, embers)

    vign = Image.new("L", (W, H), 0)
    vd = ImageDraw.Draw(vign)
    vd.ellipse([-260, -220, W + 260, H + 220], fill=70)
    vign = vign.filter(ImageFilter.GaussianBlur(150))
    dark = Image.new("RGBA", (W, H), (0, 0, 0, 255))
    bg = Image.composite(bg, dark, vign)
    return bg


def kicker_bar(draw, x, y, label, color=RED):
    draw.ellipse([x, y + 6, x + 10, y + 16], fill=color)
    draw.text((x + 20, y), label, font=f_kicker, fill=color)


def draw_progress_ring(bg, cx, cy, r, ratio, width=14, bg_color=(255, 255, 255, 45), fg_color=RED):
    size = (r + width) * 2
    layer = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    ld = ImageDraw.Draw(layer)
    bbox = [width, width, size - width, size - width]
    ld.arc(bbox, start=-90, end=270, fill=bg_color, width=width)
    if ratio > 0:
        end_angle = -90 + 360 * min(ratio, 1.0)
        ld.arc(bbox, start=-90, end=end_angle, fill=fg_color, width=width)
    bg.alpha_composite(layer, (int(cx - size / 2), int(cy - size / 2)))


def _name_block(draw, cx, y, full_name, username, user_id, name_font, sub_font, max_name_len=20):
    primary, secondary = display_identity(full_name, username, user_id, max_name_len)
    text_c(draw, cx, y, primary, name_font, CARD_WHITE)
    bbox = draw.textbbox((0, 0), primary, font=name_font)
    h = bbox[3] - bbox[1] + 10
    if secondary:
        text_c(draw, cx, y + h, secondary, sub_font, CARD_MUTED)
        h += 34
    return h


# ---------------------------------------------------------------------------
# 1. /check — report lookup card
# ---------------------------------------------------------------------------
def render_card(display_name, username, user_id, total_reports, last_report_str, avatar_img, out_path, tag=None):
    bg = make_background_web(rng_seed=user_id or 1, web_corner="tr")
    draw = ImageDraw.Draw(bg)
    kicker_bar(draw, 56, 46, "UNIVERSING · MEMBER LOOKUP")

    if total_reports == 0:
        chip_text, dot, chip_fill, chip_line = "CLEAN RECORD", (110, 235, 170, 255), (110, 235, 170, 26), (110, 235, 170, 130)
    else:
        chip_text, dot, chip_fill, chip_line = "REPORTS ON FILE", RED + (255,), RED + (26,), RED + (150,)
    chip_w = int(draw.textlength(chip_text, font=f_label2) + 58)
    chip_box = [W - 56 - chip_w, 40, W - 56, 40 + 42]
    glass(bg, chip_box, radius=21, fill=chip_fill, outline=chip_line)
    draw.ellipse([chip_box[0] + 16, chip_box[1] + 13, chip_box[0] + 30, chip_box[1] + 27], fill=dot)
    draw.text((chip_box[0] + 40, chip_box[1] + 10), chip_text, font=f_label2, fill=CARD_WHITE)

    av_size = 176
    cx = W // 2
    av_top = 110
    outer_r = av_size // 2 + 20
    draw.ellipse([cx - outer_r, av_top - 14, cx + outer_r, av_top - 14 + outer_r * 2], outline=RED + (150,), width=2)
    av = circle_avatar(avatar_img, av_size, ring_color=CARD_WHITE, ring_width=3)
    bg.alpha_composite(av, (cx - av.width // 2, av_top))

    name_y = av_top + av.height + 18
    used = _name_block(draw, cx, name_y, display_name, username, user_id, f_title2, f_sub)

    if tag:
        pill_text = tag.upper()
        pill_w = int(draw.textlength(pill_text, font=f_label2) + 30)
        py = name_y + used + 6
        pill_box = [cx - pill_w // 2, py, cx + pill_w // 2, py + 32]
        glass(bg, pill_box, radius=16, fill=RED_DIM + (55,), outline=RED + (170,))
        draw.text((pill_box[0] + 15, pill_box[1] + 6), pill_text, font=f_label2, fill=(255, 225, 225))

    stat_y0, stat_y1, gap = 470, 610, 28
    stat_w = (W - 112 - gap) // 2
    box1 = [56, stat_y0, 56 + stat_w, stat_y1]
    glass(bg, box1, radius=26)
    draw.text((box1[0] + 34, box1[1] + 28), "TOTAL REPORTS", font=f_label2, fill=CARD_MUTED)
    text_c(draw, box1[0] + stat_w // 2, box1[1] + 60, str(total_reports), f_num_lg, RED)

    box2 = [56 + stat_w + gap, stat_y0, 56 + stat_w + gap + stat_w, stat_y1]
    glass(bg, box2, radius=26)
    draw.text((box2[0] + 34, box2[1] + 28), "LAST REPORT", font=f_label2, fill=CARD_MUTED)
    text_c(draw, box2[0] + stat_w // 2, box2[1] + 60, last_report_str, f_big, CARD_WHITE)

    draw.line([(56, 650), (W - 56, 650)], fill=(255, 255, 255, 30), width=1)
    footer = "Powered by @UniversingRobot"
    fw = draw.textlength("Powered by ", font=f_footer2)
    total_w = draw.textlength(footer, font=f_footer2b)
    fx = cx - total_w / 2
    draw.text((fx, 668), "Powered by ", font=f_footer2, fill=CARD_MUTED)
    draw.text((fx + fw, 668), "@UniversingRobot", font=f_footer2b, fill=RED)

    bg.convert("RGB").save(out_path, quality=95)


# ---------------------------------------------------------------------------
# 2. /weekly (and all-time) — leaderboard card, single-column rows
# ---------------------------------------------------------------------------
def render_leaderboard_card(rows, out_path):
    """Render the all-time top ten as Universing's conversation-signal archive."""
    bg = make_background_web(rng_seed=7, web_corner="tl")
    draw = ImageDraw.Draw(bg)
    kicker_bar(draw, 56, 46, "UNIVERSING · SIGNAL ARCHIVE")
    text_c(draw, W // 2, 84, "All-Time Chatters", f_title2, CARD_WHITE)

    top_count = max((r["message_count"] for r in rows[:10]), default=1) or 1
    medal = {0: GOLD, 1: (214, 221, 239), 2: (206, 149, 92)}

    row_h, row_gap, y0 = 42, 6, 150
    for i, row in enumerate(rows[:10]):
        y = y0 + i * (row_h + row_gap)
        box = [56, y, W - 56, y + row_h]
        glass(bg, box, radius=16, fill=(255, 255, 255, 10), outline=(255, 255, 255, 26))

        badge_d = 32
        badge_color = medal.get(i, RED)
        badge_fill = badge_color + (255,) if len(badge_color) == 3 else badge_color
        draw.ellipse([box[0] + 10, y + 5, box[0] + 10 + badge_d, y + 5 + badge_d], fill=badge_fill)
        rn = str(i + 1)
        bbox = draw.textbbox((0, 0), rn, font=f_label2)
        draw.text((box[0] + 10 + badge_d / 2 - (bbox[2] - bbox[0]) / 2, y + 12), rn, font=f_label2, fill=(10, 10, 20))

        primary, secondary = display_identity(row["full_name"], row["username"], row["user_id"], max_name_len=22)
        name_x = box[0] + 62
        draw.text((name_x, y + 10), primary, font=f_sub, fill=CARD_WHITE)
        if secondary:
            pw = draw.textlength(primary, font=f_sub)
            draw.text((name_x + pw + 10, y + 14), secondary, font=f_footer2, fill=CARD_MUTED)

        frac = row["message_count"] / top_count
        pb_x0, pb_y0, pb_w, pb_h = W - 56 - 300, y + 14, 190, 12
        draw.rounded_rectangle([pb_x0, pb_y0, pb_x0 + pb_w, pb_y0 + pb_h], radius=6, fill=(255, 255, 255, 22))
        fw = max(6, int(pb_w * frac))
        draw.rounded_rectangle([pb_x0, pb_y0, pb_x0 + fw, pb_y0 + pb_h], radius=6, fill=badge_color)
        draw.text((W - 56 - 96, y + 10), f"{int(row['message_count']):,}", font=f_footer2b, fill=(220, 220, 226))

    footer_y = y0 + 10 * (row_h + row_gap) + 6
    draw.line([(56, footer_y), (W - 56, footer_y)], fill=(255, 255, 255, 26), width=1)
    text_c(draw, W // 2, footer_y + 14, "UNIVERSING • COMMUNITY CONVERSATION ARCHIVE", f_footer2, CARD_MUTED)
    bg.convert("RGB").save(out_path, "PNG", optimize=True)


# ---------------------------------------------------------------------------
# 3. /daily — top three, podium layout
# ---------------------------------------------------------------------------
def render_top_three_card(rows, title, period_label, avatar_images, out_path):
    """Render the daily/weekly top-three as a classic podium: #2 left, #1
    center (raised), #3 right."""
    bg = make_background_web(rng_seed=3, web_corner="tr")
    draw = ImageDraw.Draw(bg)
    kicker_bar(draw, 56, 46, "UNIVERSING LIVE")
    text_c(draw, W // 2, 90, title, f_title2, CARD_WHITE)
    text_c(draw, W // 2, 148, period_label.upper(), f_label2, CARD_MUTED)

    order = [1, 0, 2] if len(rows) >= 3 else list(range(len(rows)))
    slot_w, gap = 340, 30
    start_x = (W - (slot_w * 3 + gap * 2)) // 2
    base_y = 640
    heights = {0: 348, 1: 288, 2: 268}
    colors = {0: GOLD, 1: (196, 202, 224), 2: (206, 149, 92)}

    for slot_i, rank_idx in enumerate(order):
        if rank_idx >= len(rows):
            continue
        row = rows[rank_idx]
        x0 = start_x + slot_i * (slot_w + gap)
        x1 = x0 + slot_w
        h = heights[rank_idx]
        y0 = base_y - h
        accent = colors[rank_idx]
        glass(bg, [x0, y0, x1, base_y], radius=28, fill=(255, 255, 255, 14), outline=accent + (170,))

        badge_r = 26
        bcx = x0 + slot_w // 2
        draw.ellipse([bcx - badge_r, y0 - badge_r, bcx + badge_r, y0 + badge_r], fill=accent)
        rn = str(rank_idx + 1)
        bbox = draw.textbbox((0, 0), rn, font=f_rank_num)
        draw.text((bcx - (bbox[2] - bbox[0]) / 2, y0 - badge_r + 12), rn, font=f_rank_num, fill=(10, 10, 20))

        cursor_y = y0 + 30
        av_size = 118 if rank_idx == 0 else 96
        av = circle_avatar(avatar_images[rank_idx], av_size, ring_color=accent, ring_width=5)
        bg.alpha_composite(av, (bcx - av.width // 2, cursor_y))
        cursor_y += av.height + 16

        primary, secondary = display_identity(row["full_name"], row["username"], row["user_id"], max_name_len=18)
