# Rank card — "pic" theme. Composites live avatar/text onto a dev-supplied
# static template (card_assets/rank_template.png) instead of drawing the
# whole card procedurally. Coordinates below were measured numerically
# against that specific template (color-based edge detection on its accent
# strokes and icon centroids — see conversation history for the full
# methodology) and will need recalibrating if the template image is ever
# replaced with a new generation, even one that looks similar.
# ---------------------------------------------------------------------------
RANK_PIC_AVATAR_CENTER = (490, 425)
RANK_PIC_AVATAR_RADIUS = 178
RANK_PIC_NAME_Y = 610
RANK_PIC_USERNAME_Y = 665
RANK_PIC_TEXT_X = 1000
RANK_PIC_ROWS = [
    {"value_y": 248, "accent": (120, 235, 250)},   # Ranking
    {"value_y": 426, "accent": (255, 210, 110)},   # Current level
    {"value_y": 600, "accent": (120, 235, 250)},   # Total messages
]
RANK_PIC_STREAK_Y = 705
RANK_PIC_WHITE = (235, 240, 245)


def _pic_circular_crop(avatar_img, diameter):
    """Plain circular crop, no ring — pic-theme templates already have
    their own ring/bezel drawn in, so the photo just needs a clean mask."""
    img = avatar_img.resize((diameter, diameter)).convert("RGBA")
    mask = Image.new("L", (diameter, diameter), 0)
    ImageDraw.Draw(mask).ellipse([0, 0, diameter, diameter], fill=255)
    out = Image.new("RGBA", (diameter, diameter), (0, 0, 0, 0))
    out.paste(img, (0, 0), mask)
    return out


def render_rank_card_pic(profile, avatar_img, template_path, out_path):
    bg = Image.open(template_path).convert("RGBA")
    draw = ImageDraw.Draw(bg)

    f_pic_name = font("Poppins-Bold.ttf", 44)
    f_pic_username = font("Poppins-Regular.ttf", 28)
    f_pic_value = font("Poppins-Bold.ttf", 46)
    f_pic_value_sm = font("Poppins-Bold.ttf", 30)
    f_pic_label = font("Poppins-Medium.ttf", 22)

    d = RANK_PIC_AVATAR_RADIUS * 2
    av = _pic_circular_crop(avatar_img, d)
    bg.alpha_composite(av, (RANK_PIC_AVATAR_CENTER[0] - d // 2, RANK_PIC_AVATAR_CENTER[1] - d // 2))

    primary, secondary = display_identity(profile["full_name"], profile["username"], profile["user_id"], max_name_len=18)
    _pic_text_centered(draw, RANK_PIC_AVATAR_CENTER[0], RANK_PIC_NAME_Y, primary, f_pic_name, RANK_PIC_WHITE)
    if secondary:
        _pic_text_centered(draw, RANK_PIC_AVATAR_CENTER[0], RANK_PIC_USERNAME_Y, secondary, f_pic_username, RANK_PIC_ROWS[0]["accent"])

    rank_label = f"#{profile['chat_rank']}" if profile.get("chat_rank") else "—"
    draw.text((RANK_PIC_TEXT_X, RANK_PIC_ROWS[0]["value_y"]), rank_label, font=f_pic_value, fill=RANK_PIC_ROWS[0]["accent"])
    draw.text((RANK_PIC_TEXT_X, RANK_PIC_ROWS[1]["value_y"]), f"LVL {profile['level']:02d}", font=f_pic_value, fill=RANK_PIC_ROWS[1]["accent"])
    draw.text((RANK_PIC_TEXT_X, RANK_PIC_ROWS[2]["value_y"]), f"{profile['message_count']:,}", font=f_pic_value, fill=RANK_PIC_ROWS[2]["accent"])

    streak_label_w = draw.textlength("CURRENT STREAK: ", font=f_pic_label)
    draw.text(
        (RANK_PIC_TEXT_X + streak_label_w + 20, RANK_PIC_STREAK_Y),
        f"{profile.get('current_streak', 0)} Days", font=f_pic_value_sm, fill=RANK_PIC_WHITE,
    )

    bg.convert("RGB").save(out_path, "PNG", optimize=True)


def _pic_text_centered(draw, cx, y, text, fnt, fill):
    bbox = draw.textbbox((0, 0), text, font=fnt)
    w = bbox[2] - bbox[0]
    draw.text((cx - w / 2, y), text, font=fnt, fill=fill)


# ---------------------------------------------------------------------------
ORANGE = (255, 149, 62)
ORANGE_DIM = (150, 90, 40)


def _draw_flame(draw, cx, top_y, size, color):
    """Small vector flame icon — avoids relying on the emoji glyph, which
    this embedded font doesn't cover (confirmed earlier: 0 emoji codepoints
    in its cmap), so 🔥 as text renders as a tofu box."""
    w = size
    h = size * 1.3
    pts = [
        (cx, top_y),
        (cx + w * 0.32, top_y + h * 0.38),
        (cx + w * 0.30, top_y + h * 0.62),
        (cx + w * 0.12, top_y + h * 0.78),
        (cx, top_y + h),
        (cx - w * 0.12, top_y + h * 0.78),
        (cx - w * 0.30, top_y + h * 0.62),
        (cx - w * 0.32, top_y + h * 0.38),
    ]
    draw.polygon(pts, fill=color)
    inner_top = top_y + h * 0.42
    inner_h = h * 0.5
    draw.polygon([
        (cx, inner_top),
        (cx + w * 0.14, inner_top + inner_h * 0.45),
        (cx, inner_top + inner_h),
        (cx - w * 0.14, inner_top + inner_h * 0.45),
    ], fill=(20, 10, 5))


