def whisper_custom_emoji_entity(emoji_id: str, fallback: str, offset: int = 0) -> MessageEntity:
    # Telegram entity offsets/lengths use UTF-16 code units, not Python code points.
    utf16_length = len(fallback.encode("utf-16-le")) // 2
    return MessageEntity(
        type="custom_emoji",
        offset=offset,
        length=utf16_length,
        custom_emoji_id=emoji_id,
    )

WHISPER_ALERT_MAX_CHARS = 200

# Allowed Admin IDs — a fixed super-admin list. Trimmed to the dev only:
# every other admin capability comes from is_authorized() checking real
# Telegram group-admin status/permissions in GROUP_ID, so promoting
# someone as an admin in the group itself is enough — no code change
# needed to give them access to the matching bot commands.
ADMIN_IDS = [7601238522, 8135140374, 8378457375]

# Who gets DMed when something breaks. Deliberately just the one dev ID —
# error/exception alerts should go to this person only, not to every admin.
DEV_IDS = [7601238522]

# ---------------------------------------------------------------------------
# Dynamic Telegram-admin permissions — lets real group admins use bot
# commands proportional to whatever Telegram admin rights they actually
# hold, in addition to the fixed ADMIN_IDS list above. Cached briefly
# since get_chat_administrators is a real API call and commands can fire
# in bursts.
# ---------------------------------------------------------------------------
_GROUP_ADMIN_CACHE = {"data": None, "expires": 0.0}
GROUP_ADMIN_CACHE_SECONDS = 120


async def _get_group_admin_map(context: ContextTypes.DEFAULT_TYPE) -> dict:
    """Returns {user_id: ChatMember} for GROUP_ID's current admins/creator,
    refreshed at most once every GROUP_ADMIN_CACHE_SECONDS."""
    now = time.monotonic()
    if _GROUP_ADMIN_CACHE["data"] is not None and now < _GROUP_ADMIN_CACHE["expires"]:
        return _GROUP_ADMIN_CACHE["data"]
    try:
        members = await context.bot.get_chat_administrators(GROUP_ID)
        admin_map = {m.user.id: m for m in members}
    except Exception as e:
        await notify_devs(context, "_get_group_admin_map: get_chat_administrators", e)
        # Fall back to whatever we had cached (even if stale) rather than
        # locking everyone out just because one API call failed.
        admin_map = _GROUP_ADMIN_CACHE["data"] or {}
    _GROUP_ADMIN_CACHE["data"] = admin_map
    _GROUP_ADMIN_CACHE["expires"] = now + GROUP_ADMIN_CACHE_SECONDS
    return admin_map


async def is_authorized(
    context: ContextTypes.DEFAULT_TYPE, user_id: int, permission: str = None, *, update: Update = None
) -> bool:
    """True if user_id is in the fixed ADMIN_IDS list, OR is a real
    Telegram group admin/creator holding `permission` (a ChatMemberAdministrator
    attribute name like "can_restrict_members" or "can_delete_messages").
    permission=None just requires being *an* admin/creator, any rights.

    A message sent anonymously as the group is authorized because Telegram
    only permits that identity for actual group administrators.
    """
    if update is not None:
        msg = getattr(update, "message", None)
        sender_chat = getattr(msg, "sender_chat", None) if msg is not None else None
        if sender_chat is not None and sender_chat.id == GROUP_ID:
            return True

    if user_id in ADMIN_IDS:
        return True
    member = (await _get_group_admin_map(context)).get(user_id)
    if member is None:
        return False
    if member.status == ChatMemberStatus.OWNER:
        return True  # the group creator always has every permission
    if permission is None:
        return True
    return bool(getattr(member, permission, False))


async def get_notifiable_admins(context: ContextTypes.DEFAULT_TYPE, permission: str = "can_restrict_members") -> set:
    """Static ADMIN_IDS plus current Telegram admins/creator holding
    `permission` — the set of people who should get report/appeal DMs,
    since they're the ones who can actually act on them. permission=None
    means any admin/creator qualifies, regardless of specific rights."""
    ids = set(ADMIN_IDS)
    for uid, member in (await _get_group_admin_map(context)).items():
        if member.status == ChatMemberStatus.OWNER or permission is None or getattr(member, permission, False):
            ids.add(uid)
    return ids

