_DURATION_RE = re.compile(r"^(\d+)\s*([smhdw])\b\s*(.*)$", re.IGNORECASE)
_DURATION_UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400, "w": 604800}


# /tempmute and /tempban (and their /tmute, /tban aliases) fall back to this
# when no duration is given, instead of erroring out.
TEMPMUTE_DEFAULT_SECONDS = 5 * 60
TEMPBAN_DEFAULT_SECONDS = 5 * 60


def parse_duration(text: str):
    """If `text` starts with a duration like '10m', '2h', '1d', '2w',
    returns (seconds, remaining_text). Otherwise returns (None, text)
    unchanged — the whole thing is treated as a reason instead."""
    if not text:
        return None, text
    m = _DURATION_RE.match(text.strip())
    if not m:
        return None, text
    amount, unit, rest = m.groups()
    return int(amount) * _DURATION_UNITS[unit.lower()], rest.strip()


def format_duration(seconds: int) -> str:
    if seconds % 604800 == 0:
        return f"{seconds // 604800}w"
    if seconds % 86400 == 0:
        return f"{seconds // 86400}d"
    if seconds % 3600 == 0:
        return f"{seconds // 3600}h"
    if seconds % 60 == 0:
        return f"{seconds // 60}m"
    return f"{seconds}s"


async def send_moderation_dm(
    context: ContextTypes.DEFAULT_TYPE,
    target_id: int,
    emoji_key: str,
    verb: str,
    reason: str = None,
    extra_note: str = "",
):
    """DM a user about a mod action taken on them. Uses their specific
    reason if one was given, otherwise falls back to a plain notice — never
    silently says nothing."""
    reason_line = f"Reason: {html_escape(reason)}\n\n" if reason else ""
    text = (
        f"{pemoji(emoji_key)} You have been {verb} in <b>{html_escape(GROUP_NAME)}</b>.\n"
        f"{reason_line}"
        f"{extra_note}"
    )
    try:
        await context.bot.send_message(target_id, text, parse_mode="HTML")
    except Exception as e:
        # User has the bot blocked, deleted their account, or a DM just
        # can't be delivered — common and expected, not worth a dev alert
        # every time. Anything else (unexpected errors) still gets a
        # visible warning so real problems don't go unnoticed.
        error_text = str(e).lower()
        if "bot can't initiate conversation with a user" in error_text or "user is deactivated" in error_text:
            logger.debug("Moderation DM unavailable for user %s (action: %s)", target_id, verb)
        else:
            logger.warning(f"send_moderation_dm: couldn't DM user {target_id} (action: {verb}): {e}")

# ---------------------------------------------------------------------------
# Premium (custom) emoji
# ---------------------------------------------------------------------------
# Telegram lets a bot render animated "premium" emoji via HTML's <tg-emoji>
# tag: <tg-emoji emoji-id="123">🚨</tg-emoji>. Users with Telegram Premium see
# the animated custom emoji; everyone else just sees the fallback character
# inside the tag, so it's always safe to use.
#
# The IDs below are PLACEHOLDERS — swap in real custom_emoji_id values before
# these will actually render as premium emoji. To get real IDs: send/forward
# a message containing the premium emoji you want to @getidsbot (or any bot
# that echoes MessageEntity data), or pull them from
# https://t.me/addemoji/<pack_name> via the API — the entity's
# `custom_emoji_id` is what goes here.
PREMIUM_EMOJI = {
    "report":    ("5816668578270683433", "🚨"),
    "appeal":    ("5472239203590888751", "📩"),
    "stats":     ("5203993413346680064", "📊"),
    "menu":      ("5330570304332770508", "👋"),
    "hammer":    ("6325636152900453913", "🔨"),
    "mute":      ("5951817399345878399", "🔇"),
    "warn":      ("6132099600783250177", "⚠️"),
    "resetwarn": ("5816552511074476274", "♨️"),  # placeholder ID, swap when ready
    "ban":       ("4918014360267260850", "⛔️"),
    "lock":      ("5832546462478635761", "🔒"),
    "unmute":    ("5388632425314140043", "🔈"),
    "delete":    ("5408832111773757273", "🗑"),
    "purge":     ("5263003781502608081", "🧹"),  # placeholder ID, swap when ready
    "tag":       ("", "🏷"),  # no confirmed custom ID; use safe fallback
    "denied":    ("5280803324273115630", "🚫"),  # placeholder ID, swap when ready
    "usage":     ("", "ℹ️"),  # no confirmed custom ID; use safe fallback
    "error":     ("", "❗"),  # no confirmed custom ID; use safe fallback
    "lookup":    ("", "🔎"),  # no custom ID supplied; use the safe fallback symbol
    "approve":   ("5118861066981344121", "✅"),
    "reject":    ("6131800692534285654", "❌"),
    "pin":       ("", "📌"),  # no confirmed custom ID; use safe fallback
    "promote":   ("", "⬆️"),  # no confirmed custom ID; use safe fallback
    "demote":    ("", "⬇️"),  # no confirmed custom ID; use safe fallback
    "welcome_check": ("6113647841459047673", "☑"),
    "welcome_wave":  ("5443038326535759644", "💬"),
    "afk":           ("5357343970814878164", "💤"),
}


def pemoji(key: str) -> str:
    """Return the HTML <tg-emoji> tag for a premium emoji, given its key in
    PREMIUM_EMOJI. Always safe to embed in an HTML-parse-mode message —
    non-premium users just see the fallback character."""
    emoji_id, fallback = PREMIUM_EMOJI[key]
    if not emoji_id:
        return fallback
    return f'<tg-emoji emoji-id="{emoji_id}">{fallback}</tg-emoji>'


async def _reply_with_fallback(update: Update, context: ContextTypes.DEFAULT_TYPE, reply_coro, fallback_coro):
    """Shared retry logic behind safe_reply/safe_reply_photo: try the reply
    first; if Telegram rejects it only because the message being replied to
    is already gone, fall back to sending the same content as a plain
    (non-reply) message instead of failing the whole command."""
    try:
        return await reply_coro()
    except Exception as e:
        msg = str(e).lower()
        if "repl" in msg and "not found" in msg:
            return await fallback_coro()
        raise


async def safe_reply(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str, **kwargs):
    """Drop-in replacement for update.message.reply_text() that degrades
    gracefully instead of erroring if the message being replied to is
    already gone — deleted by the admin themselves, by another admin's
    cleanup, or raced by our own delayed command-deletion job. Telegram's
    Bot API rejects a reply to a missing message with a 400 unless told
    otherwise, so this catches exactly that case and resends as a plain
    (non-reply) message instead of failing the whole command."""
    return await _reply_with_fallback(
        update, context,
        lambda: update.effective_message.reply_text(text, **kwargs),
        lambda: context.bot.send_message(update.effective_chat.id, text, **kwargs),
    )


async def safe_reply_photo(update: Update, context: ContextTypes.DEFAULT_TYPE, photo, **kwargs):
    """Same degradation as safe_reply, for reply_photo(). If the first
    upload attempt fails and photo is a seekable buffer (e.g. BytesIO),
    it's rewound before the fallback send — the failed attempt already
    read it to EOF while building the request, so without this the retry
    would silently upload an empty file."""
    async def _fallback():
        if hasattr(photo, "seek"):
            photo.seek(0)
        return await context.bot.send_photo(update.effective_chat.id, photo=photo, **kwargs)

    return await _reply_with_fallback(
        update, context,
        lambda: update.effective_message.reply_photo(photo=photo, **kwargs),
        _fallback,
    )


async def deny_not_authorized(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Shared 'you can't use this' reply for every admin-only command."""
    await safe_reply(
        update, context,
        f"{pemoji('denied')} You are not authorized to use this command.",
        parse_mode="HTML",
    )


async def _delete_admin_command_message(context: ContextTypes.DEFAULT_TYPE, update: Update):
    """Schedules deletion of the admin's own command message (e.g. their
    typed '/tmute @user 1h spam') from the group, so moderation commands
    don't clutter the chat. Only called after an authorization check
    passes — an unauthorized attempt is left alone.

    Deletion is delayed ~1s rather than immediate: the command handler's
    own reply (e.g. "User X has been muted") is sent as a reply to this
    same message, and Telegram's sendMessage can 400 with "message to be
    replied not found" if the original is already gone by the time that
    reply goes out. Delaying the delete lets the reply land first.

    Best-effort either way: a failure here (e.g. bot lost delete rights)
    never blocks the actual moderation action, just gets reported to devs.
    """
    msg = update.message
    if msg is None or msg.chat_id != GROUP_ID:
        return
    if context.job_queue is not None:
        context.job_queue.run_once(
            _delayed_admin_command_delete_job,
            when=1,
            data={"chat_id": msg.chat_id, "message_id": msg.message_id},
        )
        return
    # No job queue available (job-queue extra not installed) — fall back
    # to immediate deletion rather than never cleaning up at all.
    try:
        await context.bot.delete_message(GROUP_ID, msg.message_id)
    except Exception as e:
        await notify_devs(context, "_delete_admin_command_message: delete_message", e)


async def _delayed_admin_command_delete_job(context: ContextTypes.DEFAULT_TYPE):
    data = context.job.data
    try:
        await context.bot.delete_message(data["chat_id"], data["message_id"])
    except Exception as e:
        await notify_devs(context, "_delayed_admin_command_delete_job: delete_message", e)

logging.basicConfig(
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s", level=logging.INFO
)
logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Dev error notifications
# ---------------------------------------------------------------------------
# Any error that isn't just an expected "try A, fall back to B" — i.e. one
# that would otherwise be silently swallowed or only shown to the one admin
# who happened to trigger it — gets DMed to everyone in DEV_IDS as well.
_LAST_DEV_ALERT = {}  # where -> monotonic time of last alert, for de-duping
DEV_ALERT_COOLDOWN_SECONDS = 60  # don't spam devs with the same repeated error


async def notify_devs(context: ContextTypes.DEFAULT_TYPE, where: str, exc: Exception):
    """DM every dev with a short error report. Best-effort — a failure here
    is logged but never raised, so a broken notification can't itself crash
    the bot or mask the original error."""
    logger.exception("Error in %s", where, exc_info=exc)

    now = time.monotonic()
    last = _LAST_DEV_ALERT.get(where)
    if last is not None and (now - last) < DEV_ALERT_COOLDOWN_SECONDS:
        return  # same failure point fired again very recently — skip the repeat DM
    _LAST_DEV_ALERT[where] = now

    text = (
        f"⚠️ <b>Bot error</b>\n\n"
        f"<b>Where:</b> {html_escape(where)}\n"
        f"<b>Error:</b> <code>{html_escape(f'{type(exc).__name__}: {exc}')}</code>"
    )
    for dev_id in DEV_IDS:
        try:
            await context.bot.send_message(dev_id, text, parse_mode="HTML")
        except Exception:
            logger.warning("Could not DM dev %s about an error in %s", dev_id, where)


async def global_error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    """Catches anything raised inside a handler that wasn't already caught
    locally, so no error can slip through without reaching the devs' DMs."""
    await notify_devs(context, "unhandled exception", context.error)


def friendly_error(exc: Exception) -> str:
    """Translates a raw Telegram API error into a clean, specific
    explanation for the admin who ran the command — instead of dumping
    Telegram's internal error string at them. Falls back to a generic
    message for anything not recognized; the real error still reaches
    the devs separately via notify_devs(), nothing is lost, it's just
    not shown raw to whoever ran the command."""
    msg = str(exc).lower()

    if "user_admin_invalid" in msg:
        return (
            "I can only demote or change the rights of admins that I promoted myself. "
            "This person was promoted by someone else (the owner or another admin), so "
            "Telegram won't let me touch their admin status — you'll need to change it "
            "from Telegram's own admin settings instead."
        )
    if "can't demote chat creator" in msg or "can't remove chat owner" in msg or "can't restrict chat owner" in msg:
        return "I can't take any action against the group's creator/owner."
    if "not enough rights" in msg and ("promote" in msg or "admin" in msg):
        return "I don't have the rights to change admin status here — I need the \"Add New Admins\" permission."
    if "not enough rights" in msg and ("restrict" in msg or "ban" in msg or "kick" in msg):
        return (
            "I don't have permission to do that — I might be missing the \"Restrict Members\" "
            "or \"Ban Users\" right, or this person is an admin with equal or higher standing than me."
        )
    if "not enough rights" in msg and "delete" in msg:
        return "I don't have permission to delete messages here — check that I have the \"Delete Messages\" right."
    if "not enough rights" in msg and "pin" in msg:
        return "I don't have permission to pin messages — check that I have the \"Pin Messages\" right."
    if "chat_admin_required" in msg or "not enough rights" in msg:
        return "I don't have the admin rights in this group to do that — please check my permissions."
    if "user_not_participant" in msg:
        return "That person isn't currently in the group."
    if "user_id_invalid" in msg or "peer_id_invalid" in msg:
        return "I couldn't find that user — double-check the username or ID."
    if "message to delete not found" in msg or "message can't be deleted" in msg or "message_id_invalid" in msg:
        return "That message is already gone, or too old for me to delete."
    if "message to pin not found" in msg or "message to unpin not found" in msg:
        return "That message doesn't exist anymore, so I can't pin/unpin it."
    if "bot was blocked by the user" in msg or "forbidden" in msg:
        return "I couldn't reach them — they've blocked the bot or never started a chat with it."
    if "method is available only for supergroups" in msg:
        return "This only works in supergroups, not basic groups — the group may need to be upgraded first."
    if "user is an administrator of the chat" in msg:
        return "They're currently an admin — demote them first, then try again."
    if "flood" in msg or "retry_after" in msg or "too many requests" in msg:
        return "Telegram is briefly rate-limiting me — please wait a moment and try again."

    return "Something went wrong on Telegram's end and I couldn't complete that. The dev's been notified."


def _short_for_alert(text: str, limit: int = 150) -> str:
    """Telegram's answerCallbackQuery alert popups cap out around 200
    characters total — this trims friendly_error()'s longer explanations
    so they fit alongside a short prefix instead of Telegram silently
    rejecting or truncating the call."""
    return text if len(text) <= limit else text[: limit - 1].rstrip() + "…"


# ---------------------------------------------------------------------------
# Blocked-user gate — runs before every other DM handler (registered in a
# lower handler group so it fires first). If the sender is on the block
# list, this replies with the block reason and stops the update from
# reaching any other handler (/start, /check, report/appeal flows, etc.).
# ---------------------------------------------------------------------------
async def blocked_gate(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    if not chat or chat.type != "private":
        return
    user = update.effective_user
    if not user:
        return

    info = get_block_info(user.id)
    if not info:
        return

    reason = info["reason"]
    text = f"{pemoji('denied')} You are blocked from using this bot"
    text += f" for: <b>{html_escape(reason)}</b>." if reason else "."

    if update.callback_query:
        await update.callback_query.answer(
            "You are blocked from using this bot" + (f" for: {reason}" if reason else "") + ".",
            show_alert=True,
        )
    elif update.message:
        await safe_reply(update, context, text, parse_mode="HTML")

    raise ApplicationHandlerStop


# Telegram-permission-based content locks. These change default permissions for
# regular members; Telegram administrators remain exempt by design. Links are
# intentionally excluded because Telegram has no permission that blocks URL text.
LOCK_PERMISSION_FIELDS = {
    "messages": ("can_send_messages",),
    "media": (
        "can_send_photos", "can_send_videos", "can_send_documents",
        "can_send_audios", "can_send_voice_notes", "can_send_video_notes",
    ),
    "photos": ("can_send_photos",),
    "videos": ("can_send_videos",),
    "files": ("can_send_documents",),
    "audio": ("can_send_audios",),
    "voice": ("can_send_voice_notes",),
    "video_notes": ("can_send_video_notes",),
    "stickers": ("can_send_other_messages",),
    "gifs": ("can_send_other_messages",),
    "polls": ("can_send_polls",),
    "reactions": ("can_react_to_messages",),
}
LOCK_TYPE_ALIASES = {
    "message": "messages", "text": "messages",
    "photo": "photos", "video": "videos", "document": "files",
    "documents": "files", "audios": "audio", "voices": "voice",
    "videonotes": "video_notes", "sticker": "stickers",
    "gif": "gifs", "poll": "polls", "reaction": "reactions",
}
LOCKABLE_TYPES = tuple(LOCK_PERMISSION_FIELDS)


FULL_PERMISSIONS = ChatPermissions(
    can_send_messages=True,
    can_send_audios=True,
    can_send_documents=True,
    can_send_photos=True,
    can_send_videos=True,
    can_send_video_notes=True,
    can_send_voice_notes=True,
    can_send_polls=True,
    can_send_other_messages=True,
    # Keep link previews disabled for the group, including when a mute is lifted.
    can_add_web_page_previews=False,
    can_react_to_messages=True,
)


async def enforce_group_default_permissions(application):
    """Disable link previews in the group's default member permissions.

    Existing defaults are read first so this does not reset unrelated group
    permission choices. The call is repeated on startup to keep the setting
    consistent after a manual Telegram-side change.
    """
    try:
        chat = await application.bot.get_chat(GROUP_ID)
        current = getattr(chat, "permissions", None)
        fields = (
            "can_send_messages",
            "can_send_audios",
            "can_send_documents",
            "can_send_photos",
            "can_send_videos",
            "can_send_video_notes",
            "can_send_voice_notes",
            "can_send_polls",
            "can_send_other_messages",
            "can_add_web_page_previews",
            "can_react_to_messages",
        )
        values = {
            field: getattr(current, field)
            for field in fields
            if current is not None and getattr(current, field, None) is not None
        }
        values["can_add_web_page_previews"] = False
        for fields in LOCK_PERMISSION_FIELDS.values():
            for field in fields:
                values[field] = True
        for lock_type, fields in LOCK_PERMISSION_FIELDS.items():
            if get_setting(f"lock_{lock_type}", "0") == "1":
                for field in fields:
                    values[field] = False
        await application.bot.set_chat_permissions(
            chat_id=GROUP_ID,
            permissions=ChatPermissions(**values),
            use_independent_chat_permissions=True,
        )
        logger.info("Link previews disabled in default permissions for group %s", GROUP_ID)
    except Exception as exc:
        logger.exception("Could not disable group link previews: %s", exc)


# Global in-memory storage to track message IDs sent to admins for each notification
# Structure: { key: [(admin_id, message_id), ...] }
ACTIVE_ADMIN_NOTIFS = {}

# /check flood control: max CHECK_RATE_LIMIT_MAX calls per user within
# CHECK_RATE_LIMIT_WINDOW_SECONDS, enforced both in the group and in DMs.
# In-memory only (deliberately not persisted) — losing this on a restart is
# harmless, unlike the reports/appeals data which always lives in the DB.
CHECK_RATE_LIMIT_MAX = 5
CHECK_RATE_LIMIT_WINDOW_SECONDS = 60
_CHECK_CALL_TIMES = {}  # user_id -> deque[float] of call timestamps


def check_rate_limit_ok(user_id: int) -> bool:
    """Returns True and records this call if the user is under the limit;
    returns False (without recording) if they've hit the cap."""
    now = time.monotonic()
    q = _CHECK_CALL_TIMES.setdefault(user_id, deque())
    while q and now - q[0] > CHECK_RATE_LIMIT_WINDOW_SECONDS:
        q.popleft()
    if len(q) >= CHECK_RATE_LIMIT_MAX:
        return False
    q.append(now)
    return True


# ---------------------------------------------------------------------------
# Database Setup
# ---------------------------------------------------------------------------
def get_conn():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS moderation_actions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id INTEGER NOT NULL,
            chat_title TEXT,
            user_id INTEGER NOT NULL,
            action TEXT NOT NULL,
            reason TEXT,
            admin_id INTEGER,
            created_at TEXT NOT NULL,
            status TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS appeals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            action_id INTEGER NOT NULL,
            chat_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            message TEXT,
            status TEXT NOT NULL, -- 'pending', 'approved', 'rejected'
            rejection_reason TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS reports (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id INTEGER NOT NULL,
            reporter_id INTEGER NOT NULL,
            reported_id INTEGER NOT NULL,
            reason TEXT,
            status TEXT DEFAULT 'pending', -- 'pending', 'acted', 'dismissed'
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS pending_input (
            user_id INTEGER PRIMARY KEY,
            action TEXT NOT NULL,
            step INTEGER NOT NULL,
            data TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
        """
    )
    # Local cache of users the bot has seen (group messages, DMs, callback taps).
    # Needed because Telegram's Bot API can't resolve an arbitrary @username or
    # user_id to a chat unless the bot has already had some contact with that
    # user — this cache lets /report and /check find group members reliably.
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS known_users (
            user_id INTEGER PRIMARY KEY,
            username TEXT,
            full_name TEXT,
            updated_at TEXT NOT NULL
        )
        """
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_known_users_username ON known_users (username)")
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS activity_counters (
            period_type TEXT NOT NULL,
            period_key TEXT NOT NULL,
            user_id INTEGER NOT NULL,
            username TEXT,
            full_name TEXT NOT NULL,
            message_count INTEGER NOT NULL DEFAULT 0,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (period_type, period_key, user_id)
        )
        """
    )
    cur.execute(
        "CREATE INDEX IF NOT EXISTS idx_activity_counters_rank ON activity_counters (period_type, period_key, message_count DESC)"
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS user_xp (
            user_id INTEGER PRIMARY KEY,
            username TEXT,
            full_name TEXT NOT NULL,
            xp INTEGER NOT NULL DEFAULT 0,
            last_award_at TEXT,
            updated_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS user_streaks (
            user_id INTEGER PRIMARY KEY,
            username TEXT,
            full_name TEXT NOT NULL,
            current_streak INTEGER NOT NULL DEFAULT 0,
            longest_streak INTEGER NOT NULL DEFAULT 0,
            last_active_date TEXT,
            updated_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        "CREATE INDEX IF NOT EXISTS idx_user_streaks_current ON user_streaks (current_streak DESC)"
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS afk_users (
            user_id INTEGER PRIMARY KEY,
            username TEXT,
            full_name TEXT NOT NULL,
            reason TEXT,
            started_at TEXT NOT NULL
        )
        """
    )
    # Custom "tags" (Telegram admin custom titles) set via /title, kept locally
    # too so /check can display them and /removetag knows what to clear.
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS user_tags (
            user_id INTEGER PRIMARY KEY,
            tag TEXT NOT NULL,
            set_by INTEGER,
            updated_at TEXT NOT NULL
        )
        """
    )
    # Users blocked (via /block) from interacting with the bot in DM.
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS blocked_users (
            user_id INTEGER PRIMARY KEY,
            reason TEXT,
            blocked_by INTEGER,
            blocked_at TEXT NOT NULL
        )
        """
    )
    # Stickers blocked (via /dblock) from being posted in the group — matched
    # by sticker_unique_id (Telegram's stable per-file identifier) and
    # silently deleted on sight. sticker_file_id is kept separately purely so
    # /blockedstickers can resend a preview later (file_unique_id can't be
    # used to send/resend a file, only to compare identity).
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS blocked_stickers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sticker_unique_id TEXT NOT NULL UNIQUE,
            sticker_file_id TEXT,
            sticker_set_name TEXT,
            blocked_by INTEGER,
            reason TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS blocked_sticker_packs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sticker_set_name TEXT NOT NULL UNIQUE,
            blocked_by INTEGER,
            reason TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    # Words/phrases blocked via /blacklist — matched case-insensitively as
    # whole words/phrases against every non-admin group message.
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS blacklisted_words (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            word TEXT NOT NULL UNIQUE,
            added_by INTEGER,
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS giveaway_suggestions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            message TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS admin_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            message TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS bot_settings (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS approved_users (
            user_id INTEGER PRIMARY KEY,
            approved_by INTEGER,
            approved_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS whispers (
            token TEXT PRIMARY KEY,
            sender_id INTEGER NOT NULL,
            sender_name TEXT NOT NULL,
            target_id INTEGER,
            target_username TEXT NOT NULL,
            target_label TEXT NOT NULL,
            message TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending',
            created_at TEXT NOT NULL,
            read_at TEXT,
            read_by INTEGER
        )
        """
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_whispers_target ON whispers (target_username, status)")
    conn.commit()
    conn.close()


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def get_setting(key: str, default: str = None) -> str:
    conn = get_conn()
    row = conn.execute("SELECT value FROM bot_settings WHERE key = ?", (key,)).fetchone()
    conn.close()
    return row["value"] if row else default


def set_setting(key: str, value: str):
    conn = get_conn()
    conn.execute(
        "INSERT INTO bot_settings (key, value) VALUES (?, ?) "
        "ON CONFLICT(key) DO UPDATE SET value = excluded.value",
        (key, value),
    )
    conn.commit()
    conn.close()


# ---------------------------------------------------------------------------
# Card theme switching — "code" (procedural PIL drawing, what every card
# uses today) vs "pic" (a dev-supplied static background template per card,
# with live text/avatar composited on top). Restricted to DEV_IDS, not the
# general ADMIN_IDS list — this is a design-level control, not moderation.
#
# "pic" mode has no actual template assets wired in yet (that's a separate
# follow-up once template images exist), so render call sites should treat
# get_card_theme() == "pic" with no matching asset as "fall back to code"
# rather than erroring — this setting alone doesn't change how any card
# looks yet, it just makes the switch available and persisted for when it
# does.
# ---------------------------------------------------------------------------
CARD_THEME_KEY = "card_theme"
CARD_THEMES = ("code", "pic")
CARD_ASSETS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "card_assets")


def get_card_theme() -> str:
    return get_setting(CARD_THEME_KEY, "code") or "code"


def set_card_theme(theme: str):
    set_setting(CARD_THEME_KEY, theme)


def _card_asset_path(name: str) -> str | None:
    """Returns the path to a pic-theme template if it actually exists on
    disk, else None — the single place every render dispatcher checks
    before deciding whether "pic" mode has real content to use yet."""
    path = os.path.join(CARD_ASSETS_DIR, name)
    return path if os.path.exists(path) else None


async def cmd_theme(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    if not user or user.id not in DEV_IDS:
        return  # silent — this isn't a moderation command, no need to announce it exists
    current = get_card_theme()
    if not context.args:
        await safe_reply(
            update, context,
            f"🎛 <b>Card theme:</b> {current}\n\nUsage: <code>/theme code</code> or <code>/theme pic</code>",
            parse_mode="HTML",
        )
        return
    choice = context.args[0].lower()
    if choice not in CARD_THEMES:
        await safe_reply(update, context, f"Unknown theme '{choice}'. Options: {', '.join(CARD_THEMES)}", parse_mode="HTML")
        return
    set_card_theme(choice)
    note = "" if choice == "code" else " (no template images configured yet — cards will still render in 'code' style until those are added)"
    await safe_reply(update, context, f"🎛 Card theme set to <b>{choice}</b>{note}.", parse_mode="HTML")


# ---------------------------------------------------------------------------
# Storage cleanup — the only tables that grow without bound are
# moderation_actions, reports, and appeals (everything else is one row per
# user/tag and stays roughly flat). This periodically purges rows from
# those three that are no longer functionally needed:
#   - moderation_actions: rows already 'lifted', or actions with no lift
#     concept at all ('kick', 'delete', 'purge' — just point-in-time log
#     lines). Active mutes/bans and active warns (still counting toward
#     the warn threshold) are NEVER touched, no matter how old.
#   - reports / appeals: already resolved ('acted'/'dismissed' or
#     'approved'/'rejected'). Anything still 'pending' stays regardless
#     of age since it's awaiting admin action.
# /stats' totals will reflect activity within DB_RETENTION_DAYS once old
# resolved rows start getting purged, rather than an all-time count.
# ---------------------------------------------------------------------------
DB_RETENTION_DAYS = 90


async def cleanup_old_records_job(context: ContextTypes.DEFAULT_TYPE):
    cutoff = (datetime.now(timezone.utc) - timedelta(days=DB_RETENTION_DAYS)).isoformat()
    conn = get_conn()
    try:
        conn.execute(
            "DELETE FROM moderation_actions WHERE created_at < ? "
            "AND (status = 'lifted' OR action IN ('kick', 'delete', 'purge'))",
            (cutoff,),
        )
        conn.execute(
            "DELETE FROM reports WHERE created_at < ? AND status IN ('acted', 'dismissed')",
            (cutoff,),
        )
        conn.execute(
            "DELETE FROM appeals WHERE created_at < ? AND status IN ('approved', 'rejected')",
            (cutoff,),
        )
        conn.commit()
        # DELETE alone doesn't shrink the .db file on disk — it just frees
        # internal pages for reuse. VACUUM reclaims that space for real.
        conn.execute("VACUUM")
    except Exception as e:
        await notify_devs(context, "cleanup_old_records_job", e)
    finally:
        conn.close()


def set_pending(user_id, action, step, data: dict):
    conn = get_conn()
    conn.execute(
        "INSERT OR REPLACE INTO pending_input (user_id, action, step, data, created_at) VALUES (?, ?, ?, ?, ?)",
        (user_id, action, step, json.dumps(data), now_iso()),
    )
    conn.commit()
    conn.close()


def get_pending(user_id):
    conn = get_conn()
    row = conn.execute("SELECT * FROM pending_input WHERE user_id = ?", (user_id,)).fetchone()
    conn.close()
    if not row:
        return None
    return {"action": row["action"], "step": row["step"], "data": json.loads(row["data"])}


def clear_pending(user_id):
    conn = get_conn()
    conn.execute("DELETE FROM pending_input WHERE user_id = ?", (user_id,))
    conn.commit()
    conn.close()


