async def handle_join_request(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Approve join requests automatically only when the admin toggle is enabled."""
    request = update.chat_join_request
    if not request or request.chat.id != GROUP_ID or not _AUTO_APPROVE_JOIN_REQUESTS:
        return
    try:
        await context.bot.approve_chat_join_request(request.chat.id, request.from_user.id)
    except Exception as e:
        await notify_devs(context, "autoapprove: approve_chat_join_request", e)


# Welcome message for new group members.
# ---------------------------------------------------------------------------
async def welcome_new_members(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.effective_message
    if not msg or not msg.new_chat_members:
        return

    for member in msg.new_chat_members:
        if member.id == context.bot.id:
            continue  # the bot itself being added to the group, not a member to greet

        mention = f"@{member.username}" if member.username else html_escape(member.full_name)
        await context.bot.send_message(
            GROUP_ID,
            f"Hey {mention} {pemoji('welcome_check')}\n"
            f"Welcome to {html_escape(GROUP_NAME)} Gc! {pemoji('welcome_wave')}",
            parse_mode="HTML",
        )


async def welcome_approved_member(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Welcome a user after an administrator approves their join request."""
    change = update.chat_member
    if not change or change.chat.id != GROUP_ID:
        return

    old_status = change.old_chat_member.status
    new_status = change.new_chat_member.status
    approved_from_request = (
        old_status in {ChatMemberStatus.LEFT, ChatMemberStatus.BANNED}
        and new_status in {
            ChatMemberStatus.MEMBER,
            ChatMemberStatus.ADMINISTRATOR,
            ChatMemberStatus.OWNER,
        }
    )
    if not approved_from_request:
        return

    member = change.new_chat_member.user
    if member.id == context.bot.id:
        return

    mention = f"@{member.username}" if member.username else html_escape(member.full_name)
    await context.bot.send_message(
        GROUP_ID,
        f"Hey {mention} {pemoji('welcome_check')}\n"
        f"Welcome to {html_escape(GROUP_NAME)} Gc! {pemoji('welcome_wave')}",
        parse_mode="HTML",
    )


async def track_group_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await track_user(update.effective_user)
    msg = update.effective_message
    if not msg or (msg.text and msg.text.startswith("/")):
        return
    if not _has_user_content(msg):
        return  # service notification (tag/title changed, pinned, etc.) — not something the user actually sent
    record_activity(update.effective_user)
    record_streak_activity(update.effective_user)
    award_message_xp(update.effective_user)


def _afk_display_name(user_id: int, username: str | None, full_name: str | None) -> str:
    if username:
        return f"@{html_escape(username)}"
    return f'<a href="tg://user?id={user_id}">{html_escape(full_name or f"User {user_id}")}</a>'


def _afk_elapsed(started_at: str) -> str:
    try:
        started = datetime.fromisoformat(started_at)
        seconds = max(1, int((datetime.now(timezone.utc) - started).total_seconds()))
    except Exception:
        seconds = 1
    if seconds >= 86400:
        days = seconds // 86400
        return f"{days} day" if days == 1 else f"{days} days"
    if seconds >= 3600:
        return f"{seconds // 3600}h"
    if seconds >= 60:
        return f"{seconds // 60}m"
    return f"{seconds}s"


async def cmd_afk(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mark the sender AFK in the configured group until their next message."""
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user:
        return
    reason = " ".join(context.args).strip() if context.args else None
    conn = get_conn()
    conn.execute(
        "INSERT OR REPLACE INTO afk_users (user_id, username, full_name, reason, started_at) VALUES (?, ?, ?, ?, ?)",
        (user.id, user.username, user.full_name, reason or None, now_iso()),
    )
    conn.commit()
    conn.close()
    text = f"{pemoji('afk')} {_afk_display_name(user.id, user.username, user.full_name)} is now AFK"
    if reason:
        text += f" — {html_escape(reason)}"
    # Send the established AFK status as a normal group message, not as a
    # reply, then remove only the command that activated AFK.
    await context.bot.send_message(GROUP_ID, text + ".", parse_mode="HTML")
    try:
        await context.bot.delete_message(GROUP_ID, msg.message_id)
    except Exception:
        pass


async def check_afk_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Announce AFK users when mentioned and announce their return on a new message."""
    msg = update.effective_message
    sender = update.effective_user
    if not msg or not sender or sender.is_bot:
        return

    conn = get_conn()
    own_afk = conn.execute(
        "SELECT username, full_name, reason, started_at FROM afk_users WHERE user_id = ?", (sender.id,)
    ).fetchone()
    if own_afk:
        conn.execute("DELETE FROM afk_users WHERE user_id = ?", (sender.id,))
        conn.commit()
        conn.close()
        # Keep the user's return message visible. Only the original /afk
        # command is deleted during activation.
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('afk')} {_afk_display_name(sender.id, sender.username, sender.full_name)} is back after being AFK for {_afk_elapsed(own_afk['started_at'])}.",
            parse_mode="HTML",
        )
        return

    targets = set()
    reply = msg.reply_to_message
    if reply and reply.from_user and reply.from_user.id != sender.id:
        targets.add(reply.from_user.id)
    raw_text = msg.text or msg.caption or ""
    for username in re.findall(r"(?<![A-Za-z0-9_])@([A-Za-z0-9_]{3,32})", raw_text):
        row = conn.execute("SELECT user_id FROM known_users WHERE username = ?", (username.lower(),)).fetchone()
        target_id = row["user_id"] if row else None
        if target_id is None:
            target_id, _ = await resolve_user_id(context, f"@{username}")
        if target_id and target_id != sender.id:
            targets.add(target_id)
    notices = []
    for target_id in targets:
        row = conn.execute(
            "SELECT username, full_name, reason FROM afk_users WHERE user_id = ?", (target_id,)
        ).fetchone()
        if not row:
            continue
        target_label = _afk_display_name(target_id, row["username"], row["full_name"])
        notice = f"{pemoji('afk')} {target_label} is AFK"
        if row["reason"]:
            notice += f" — {html_escape(row['reason'])}"
        notices.append(notice + ".")
    conn.close()
    if notices:
        await context.bot.send_message(GROUP_ID, "\n".join(notices), parse_mode="HTML")


async def resolve_user_id(context: ContextTypes.DEFAULT_TYPE, identifier: str):
    identifier = identifier.strip()
    if identifier.startswith("@"):
        identifier = identifier[1:]

    # --- Numeric user ID ---
    if identifier.lstrip("-").isdigit():
        user_id = int(identifier)
        # get_chat_member works for any member of a group the bot is in,
        # even if the bot has never had direct contact with that user.
        try:
            member = await context.bot.get_chat_member(GROUP_ID, user_id)
            return member.user.id, member.user.full_name
        except Exception:
            pass
        try:
            chat = await context.bot.get_chat(user_id)
            return chat.id, chat.full_name
        except Exception:
            pass
        # Fall back to the cache in case the member left the group meanwhile.
        conn = get_conn()
        row = conn.execute("SELECT user_id, full_name FROM known_users WHERE user_id = ?", (user_id,)).fetchone()
        conn.close()
        if row:
            return row["user_id"], row["full_name"]
        return user_id, f"User {user_id}"

    # --- @username lookup ---
    uname = identifier.lower()
    conn = get_conn()
    row = conn.execute("SELECT user_id, full_name FROM known_users WHERE username = ?", (uname,)).fetchone()
    conn.close()
    if row:
        return row["user_id"], row["full_name"]

    # Last resort: only works if the bot already knows this user.
    try:
        chat = await context.bot.get_chat(f"@{identifier}")
        return chat.id, chat.full_name
    except Exception:
        return None, None


async def check_daily_limit(user_id: int, table_name: str, column_name: str) -> bool:
    conn = get_conn()
    since = (datetime.now(timezone.utc) - timedelta(days=1)).isoformat()
    count = conn.execute(
        f"SELECT COUNT(*) as c FROM {table_name} WHERE {column_name} = ? AND created_at > ?",
        (user_id, since),
    ).fetchone()["c"]
    conn.close()
    return count < DAILY_LIMIT


async def cleanup_admin_messages(context: ContextTypes.DEFAULT_TYPE, key: str):
    """Deletes or updates messages sent to all admins once an action is taken by any single admin."""
    if key in ACTIVE_ADMIN_NOTIFS:
        for admin_id, msg_id in ACTIVE_ADMIN_NOTIFS[key]:
            try:
                await context.bot.delete_message(chat_id=admin_id, message_id=msg_id)
            except Exception:
                try:
                    await context.bot.edit_message_reply_markup(
                        chat_id=admin_id, message_id=msg_id, reply_markup=None
                    )
                except Exception:
                    pass
        del ACTIVE_ADMIN_NOTIFS[key]


# ---------------------------------------------------------------------------
# /alive — public health check for the group and bot DM
# ---------------------------------------------------------------------------
ALIVE_RATE_LIMIT_SECONDS = 30
_LAST_ALIVE_CALL = 0.0


async def cmd_alive(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global _LAST_ALIVE_CALL
    started = time.perf_counter()
    now = time.monotonic()
    elapsed = now - _LAST_ALIVE_CALL
    if _LAST_ALIVE_CALL and elapsed < ALIVE_RATE_LIMIT_SECONDS:
        wait = max(1, int(ALIVE_RATE_LIMIT_SECONDS - elapsed + 0.999))
        await safe_reply(
            update,
            context,
            f"Please wait {wait}s before using /alive again.",
        )
        return

    # Set this before the first await so the limit is global across group and DM.
    _LAST_ALIVE_CALL = now
    latency_ms = (time.perf_counter() - started) * 1000
    await safe_reply(
        update,
        context,
        f"Universing support is alive\nlatency :- {latency_ms:.2f} ms",
    )


