async def send_main_menu(context: ContextTypes.DEFAULT_TYPE, user_id: int, edit_query=None):
    # 2×2 layout: moderation appeal, admin contact, giveaway suggestion, report.
    first_name = None
    if edit_query and getattr(edit_query, "from_user", None):
        first_name = edit_query.from_user.first_name
    if not first_name:
        try:
            chat = await context.bot.get_chat(user_id)
            first_name = getattr(chat, "first_name", None) or getattr(chat, "full_name", None)
        except Exception:
            first_name = None
    first_name = html_escape(first_name or "there")
    buttons = [
        [
            InlineKeyboardButton("Appeal Mute/Ban", callback_data="appeal_start", style="success"),
            InlineKeyboardButton("Message Admins", callback_data="msgadmins_start", style="success"),
        ],
        [
            InlineKeyboardButton("Suggest a Giveaway", callback_data="giveaway_start", style="primary"),
            InlineKeyboardButton("Report a User", callback_data="report_start", style="danger"),
        ],
    ]
    text = (
        f"Hey {first_name},\n"
        "Welcome to Universing support,\n"
        "Appeal your mute or ban via the appeal button\n\n"
        "Send /help to know more about commands and the bot"
    )
    markup = InlineKeyboardMarkup(buttons)
    if edit_query:
        await edit_query.edit_message_text(text, reply_markup=markup, parse_mode="HTML")
    else:
        await context.bot.send_message(user_id, text, reply_markup=markup, parse_mode="HTML")


async def cmd_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await track_user(update.effective_user)
    clear_pending(update.effective_user.id)

    # The feedback deep link opens the same DM prompt as /feedback.
    if (
        update.effective_chat
        and update.effective_chat.type == "private"
        and context.args
        and context.args[0].lower() == "feedback"
    ):
        await cmd_feedback(update, context)
        return

    if (
        update.effective_chat
        and update.effective_chat.type == "private"
        and context.args
        and context.args[0].lower() == "tag"
    ):
        await send_tag_menu(update, context)
        return

    # Permission links are bound to the admin who ran /info. They can only
    # open in that admin's private chat and cannot be forwarded or reused by
    # another admin.
    if (
        update.effective_chat
        and update.effective_chat.type == "private"
        and context.args
        and context.args[0].lower().startswith("perm_")
    ):
        parts = context.args[0].split("_")
        if len(parts) == 3:
            try:
                linked_admin_id = int(parts[1])
                target_id = int(parts[2])
            except ValueError:
                linked_admin_id = target_id = 0
            if linked_admin_id and target_id and update.effective_user.id == linked_admin_id:
                await send_permission_panel(context, linked_admin_id, target_id)
            else:
                await safe_reply(update, context, "This permission link is not assigned to you.")
            return

    # Keep the interactive support menu in the bot's private chat only.
    if update.effective_chat and update.effective_chat.type != "private":
        await safe_reply(
            update,
            context,
            "You can use this command only in the bot's DM.",
        )
        return

    await send_main_menu(context, update.effective_user.id)


async def cmd_cancel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    clear_pending(update.effective_user.id)
    await safe_reply(update, context, "Cancelled.")
    await send_main_menu(context, update.effective_user.id)


