# ---------------------------------------------------------------------------
# /mute, /unmute, /ban — direct moderation commands (admin-only, group-only)
# ---------------------------------------------------------------------------
async def _do_mute(update: Update, context: ContextTypes.DEFAULT_TYPE, *, require_duration: bool):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, remainder = await _resolve_target_from_reply_or_args(update, context, tag_follows=True)
    if target_id is None:
        if require_duration:
            await safe_reply(update, context, 
                f"{pemoji('usage')} Usage:\n"
                "• Reply to their message with <code>/tempmute [duration] &lt;reason&gt;</code>\n"
                "• Or <code>/tempmute @username [duration] &lt;reason&gt;</code>\n\n"
                f"Duration is optional here too (e.g. <code>30m</code>, <code>2h</code>, <code>1d</code>, <code>1w</code>) — "
                f"leave it out and it defaults to {format_duration(TEMPMUTE_DEFAULT_SECONDS)}.\n"
                "Example: <code>/tempmute @user 2h spamming links</code>",
                parse_mode="HTML",
            )
        else:
            await safe_reply(update, context, 
                f"{pemoji('usage')} Usage:\n"
                "• Reply to their message with <code>/mute [duration] &lt;reason&gt;</code>\n"
                "• Or <code>/mute @username [duration] &lt;reason&gt;</code>\n\n"
                "Duration is optional (e.g. <code>30m</code>, <code>2h</code>, <code>1d</code>, <code>1w</code>) — omit it for an indefinite mute.\n"
                "Example: <code>/mute @user 2h spamming links</code>",
                parse_mode="HTML",
            )
        return

    if target_id in ADMIN_IDS or await is_authorized(context, target_id):
        await safe_reply(update, context, 
            f"{pemoji('error')} 😂 Are you blind? {html_escape(target_name)} is an admin — you can't mute them. Nice try though.",
            parse_mode="HTML",
        )
        return

    duration_seconds, reason = parse_duration(remainder)
    reason = reason.strip() or None

    if require_duration and not duration_seconds:
        # /tmute or /tempmute with no duration given — default rather than error.
        duration_seconds = TEMPMUTE_DEFAULT_SECONDS

    until_date = None
    if duration_seconds:
        until_date = datetime.now(timezone.utc) + timedelta(seconds=duration_seconds)

    try:
        await context.bot.restrict_chat_member(
            GROUP_ID,
            target_id,
            permissions=ChatPermissions(can_send_messages=False),
            until_date=until_date,
        )
    except Exception as e:
        await notify_devs(context, "cmd_mute: restrict_chat_member", e)
        await safe_reply(update, context, 
            f"{pemoji('error')} Couldn't mute {html_escape(target_name)}: {friendly_error(e)}",
            parse_mode="HTML",
        )
        return

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'mute', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, target_id, reason, actor.id, now_iso()),
    )
    conn.commit()
    conn.close()

    duration_note = f" for {format_duration(duration_seconds)}" if duration_seconds else ""
    await safe_reply(update, context, 
        f"{pemoji('mute')} {html_escape(target_name)} has been muted{duration_note}."
        + (f" Reason: {html_escape(reason)}" if reason else ""),
        parse_mode="HTML",
        reply_markup=_quick_unmute_markup(target_id),
    )

    extra_note = (
        f"This mute lifts automatically in {format_duration(duration_seconds)}.\n\n"
        if duration_seconds
        else ""
    )
    extra_note += (
        "If you think this was a mistake, use /start in this chat and choose "
        "\"Appeal Mute/Ban\"."
    )
    await send_moderation_dm(context, target_id, "mute", "muted", reason=reason, extra_note=extra_note)

    if duration_seconds and context.job_queue is not None:
        context.job_queue.run_once(
            _mute_expired_job, when=duration_seconds, data={"target_id": target_id}
        )


async def _mute_expired_job(context: ContextTypes.DEFAULT_TYPE):
    """Fires when a timed /mute's duration elapses. Telegram itself already
    lifts the restriction (we passed until_date), this just keeps the DB and
    the user in the loop."""
    target_id = context.job.data["target_id"]
    conn = get_conn()
    conn.execute(
        "UPDATE moderation_actions SET status = 'lifted' "
        "WHERE user_id = ? AND action = 'mute' AND status = 'active'",
        (target_id,),
    )
    conn.commit()
    conn.close()
    try:
        await context.bot.send_message(
            target_id,
            f"{pemoji('mute')} Your mute in <b>{html_escape(GROUP_NAME)}</b> has expired — "
            "you can send messages again.",
            parse_mode="HTML",
        )
    except Exception:
        pass


async def cmd_mute(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _do_mute(update, context, require_duration=False)


async def cmd_tempmute(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _do_mute(update, context, require_duration=True)


# ---------------------------------------------------------------------------
# NSFW protection — see NSFW_ENABLED / SIGHTENGINE_* near the top for setup.
# Scores photos/stickers/GIFs/image-documents posted in the group; anything
# over NSFW_SCORE_THRESHOLD gets deleted and the sender warned (reusing the
# same warn-count / auto-mute-at-threshold logic as /warn).
# ---------------------------------------------------------------------------
async def _score_nsfw(file_url: str) -> float:
    """Returns a 0.0 (safe) - 1.0 (explicit) nudity score via Sightengine.
    Fails OPEN on any error — an API hiccup or bad response should never
    start deleting people's normal photos."""
    if not NSFW_ENABLED:
        return 0.0
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            resp = await client.get(
                "https://api.sightengine.com/1.0/check.json",
                params={
                    "url": file_url,
                    "models": "nudity-2.1",
                    "api_user": SIGHTENGINE_API_USER,
                    "api_secret": SIGHTENGINE_API_SECRET,
                },
            )
            data = resp.json()
        if data.get("status") != "success":
            return 0.0
        nudity = data.get("nudity", {})
        return max(
            float(nudity.get("sexual_activity", 0) or 0),
            float(nudity.get("sexual_display", 0) or 0),
            float(nudity.get("erotica", 0) or 0),
        )
    except Exception:
        return 0.0


async def _handle_nsfw_violation(context: ContextTypes.DEFAULT_TYPE, msg, sender):
    try:
        await msg.delete()
    except Exception as e:
        await notify_devs(context, "nsfw: delete_message", e)

    target_name = sender.full_name

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'warn', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, sender.id, "Posted NSFW content (auto-detected)", None, now_iso()),
    )
    conn.commit()
    warn_count = conn.execute(
        "SELECT COUNT(*) AS c FROM moderation_actions WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
        (GROUP_ID, sender.id),
    ).fetchone()["c"]
    conn.close()

    try:
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('warn')} A message from {html_escape(target_name)} was removed for NSFW content. "
            f"Warned ({warn_count}/{WARN_THRESHOLD}).",
            parse_mode="HTML",
        )
    except Exception as e:
        await notify_devs(context, "nsfw: group announcement", e)

    if warn_count >= WARN_THRESHOLD:
        until_date = datetime.now(timezone.utc) + timedelta(seconds=WARN_AUTO_MUTE_SECONDS)
        try:
            await context.bot.restrict_chat_member(
                GROUP_ID, sender.id, permissions=ChatPermissions(can_send_messages=False), until_date=until_date
            )
            conn = get_conn()
            conn.execute(
                "UPDATE moderation_actions SET status = 'lifted' WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
                (GROUP_ID, sender.id),
            )
            conn.execute(
                "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
                "VALUES (?, ?, ?, 'mute', ?, ?, ?, 'active')",
                (GROUP_ID, GROUP_NAME, sender.id, f"Auto-mute: reached {WARN_THRESHOLD} warnings", None, now_iso()),
            )
            conn.commit()
            conn.close()

            await context.bot.send_message(
                GROUP_ID,
                f"{pemoji('mute')} {html_escape(target_name)} reached {WARN_THRESHOLD} warnings and has been "
                f"auto-muted for {format_duration(WARN_AUTO_MUTE_SECONDS)}.",
                parse_mode="HTML",
            )
            await send_moderation_dm(
                context, sender.id, "mute", "muted",
                extra_note=(
                    f"You reached {WARN_THRESHOLD} warnings in <b>{html_escape(GROUP_NAME)}</b> "
                    f"(most recently for NSFW content) and were automatically muted for "
                    f"{format_duration(WARN_AUTO_MUTE_SECONDS)}.\n\n"
                    "If you think this was a mistake, use /start in this chat and choose "
                    "\"Appeal Mute/Ban\"."
                ),
            )
            if context.job_queue is not None:
                context.job_queue.run_once(
                    _mute_expired_job, when=WARN_AUTO_MUTE_SECONDS, data={"target_id": sender.id}
                )
        except Exception as e:
            await notify_devs(context, "nsfw: auto-mute after threshold", e)
    else:
        await send_moderation_dm(
            context, sender.id, "warn", "warned",
            reason="Posted NSFW content",
            extra_note=(
                f"You are at {warn_count}/{WARN_THRESHOLD} warnings — reaching {WARN_THRESHOLD} "
                "results in an automatic mute."
            ),
        )


# ---------------------------------------------------------------------------
# Silent blocked-sticker deletion — checked ahead of the NSFW scanner (see
# handler-group ordering in main()) so a blocked sticker gets deleted
# immediately without also burning a Sightengine API call on something
# that's getting removed anyway. Raises ApplicationHandlerStop when it
# deletes one, which also skips the passive user-tracker for that (now
# gone) message; non-blocked stickers just fall through untouched so every
# later handler group still runs on them exactly as before.
# ---------------------------------------------------------------------------
async def check_blocked_sticker(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.effective_message
    if not msg or not msg.sticker:
        return
    sender = update.effective_user
    if sender and (is_approved(sender.id) or await is_authorized(context, sender.id)):
        return  # admins and approved users are exempt

    conn = get_conn()
    row = conn.execute(
        "SELECT id FROM blocked_stickers WHERE sticker_unique_id = ?",
        (msg.sticker.file_unique_id,),
    ).fetchone()
    pack_row = None
    if not row and msg.sticker.set_name:
        pack_row = conn.execute(
            "SELECT id FROM blocked_sticker_packs WHERE sticker_set_name = ?",
            (msg.sticker.set_name,),
        ).fetchone()
    conn.close()
    if not row and not pack_row:
        return

    try:
        await context.bot.delete_message(GROUP_ID, msg.message_id)
    except Exception as e:
        await notify_devs(context, "check_blocked_sticker: delete_message", e)

    raise ApplicationHandlerStop


async def check_nsfw_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not NSFW_ENABLED:
        return
    msg = update.effective_message
    if not msg or not msg.from_user or msg.from_user.is_bot:
        return
    if await is_authorized(context, msg.from_user.id):
        return  # admins are exempt — they enforce this, they're not subject to it
    if is_approved(msg.from_user.id):
        return  # explicitly approved via /free — passive detectors leave them alone

    file_id = None
    if msg.photo:
        file_id = msg.photo[-1].file_id
    elif msg.sticker and not msg.sticker.is_animated and not msg.sticker.is_video:
        file_id = msg.sticker.file_id
    elif msg.animation:
        file_id = msg.animation.file_id
    elif msg.document and (msg.document.mime_type or "").startswith("image/"):
        file_id = msg.document.file_id

    if not file_id:
        return  # video/text/audio/etc. — out of scope, see note below

    try:
        tg_file = await context.bot.get_file(file_id)
        file_url = tg_file.file_path
        if not file_url.startswith("http"):
            file_url = f"https://api.telegram.org/file/bot{BOT_TOKEN}/{file_url}"
    except Exception:
        return  # couldn't fetch the file — skip silently, not worth a dev alert

    score = await _score_nsfw(file_url)
    if score >= NSFW_SCORE_THRESHOLD:
        await _handle_nsfw_violation(context, msg, msg.from_user)


# ---------------------------------------------------------------------------
# Anti-spam / anti-flood — see _SPAM_CONFIG / SPAM_LIMIT_DEFAULT /
# FLOOD_WINDOW_SECONDS / SPAM_MUTE_SECONDS near the top for the settings.
# ---------------------------------------------------------------------------
async def _delete_flood_messages(context: ContextTypes.DEFAULT_TYPE, message_ids):
    """Delete only the triggering spammer's tracked consecutive messages."""
    for message_id in message_ids or []:
        try:
            await context.bot.delete_message(GROUP_ID, message_id)
        except Exception as e:
            if "message to delete not found" in str(e).lower():
                logger.debug("Flood message %s was already deleted", message_id)
            else:
                logger.warning("Could not delete flood message %s: %s", message_id, e)


async def _handle_flood_violation(context: ContextTypes.DEFAULT_TYPE, user, message_ids=None):
    now_mono = time.monotonic()
    last_action = _FLOOD_ACTION_LAST.get(user.id, 0.0)
    if now_mono - last_action < FLOOD_ACTION_COOLDOWN_SECONDS:
        await _delete_flood_messages(context, message_ids)
        return
    _FLOOD_ACTION_LAST[user.id] = now_mono
    target_name = user.full_name
    limit = _SPAM_CONFIG["limit"]
    action = _SPAM_CONFIG.get("action", "mute")
    if action == "warn":
        conn = get_conn()
        conn.execute(
            "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
            "VALUES (?, ?, ?, 'warn', ?, ?, ?, 'active')",
            (GROUP_ID, GROUP_NAME, user.id, f"Flooding ({limit}+ messages in a row, warning mode)", None, now_iso()),
        )
        warn_count = conn.execute(
            "SELECT COUNT(*) AS c FROM moderation_actions WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
            (GROUP_ID, user.id),
        ).fetchone()["c"]
        conn.commit()
        conn.close()
        await _delete_flood_messages(context, message_ids)
        try:
            await context.bot.send_message(
                GROUP_ID,
                f"{pemoji('warn')} {html_escape(target_name)} was warned for flooding "
                f"({limit}+ messages in a row). Warning {warn_count}.",
                parse_mode="HTML",
            )
        except Exception as e:
            await notify_devs(context, "antiflood: warning announcement", e)

        if warn_count >= WARN_THRESHOLD:
            until_date = datetime.now(timezone.utc) + timedelta(seconds=WARN_AUTO_MUTE_SECONDS)
            try:
                await context.bot.restrict_chat_member(
                    GROUP_ID,
                    user.id,
                    permissions=ChatPermissions(can_send_messages=False),
                    until_date=until_date,
                )
                conn = get_conn()
                conn.execute(
                    "UPDATE moderation_actions SET status = 'lifted' "
                    "WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
                    (GROUP_ID, user.id),
                )
                conn.execute(
                    "INSERT INTO moderation_actions "
                    "(chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
                    "VALUES (?, ?, ?, 'mute', ?, ?, ?, 'active')",
                    (
                        GROUP_ID,
                        GROUP_NAME,
                        user.id,
                        f"Auto-mute: reached {WARN_THRESHOLD} warnings from flooding",
                        None,
                        now_iso(),
                    ),
                )
                conn.commit()
                conn.close()

                await context.bot.send_message(
                    GROUP_ID,
                    f"{pemoji('mute')} {html_escape(target_name)} reached {WARN_THRESHOLD} warnings "
                    f"and has been auto-muted for {format_duration(WARN_AUTO_MUTE_SECONDS)}.",
                    parse_mode="HTML",
                )
                await send_moderation_dm(
                    context,
                    user.id,
                    "mute",
                    "muted",
                    extra_note=(
                        f"You reached {WARN_THRESHOLD} warnings for flooding in "
                        f"<b>{html_escape(GROUP_NAME)}</b> and were automatically muted for "
                        f"{format_duration(WARN_AUTO_MUTE_SECONDS)}.\n\n"
                        "If you think this was a mistake, use /start in this chat and choose "
                        '"Appeal Mute/Ban".'
                    ),
                )
                if context.job_queue is not None:
                    context.job_queue.run_once(
                        _mute_expired_job,
                        when=WARN_AUTO_MUTE_SECONDS,
                        data={"target_id": user.id},
                    )
            except Exception as e:
                await notify_devs(context, "antiflood: auto-mute after warning threshold", e)
        else:
            await send_moderation_dm(
                context,
                user.id,
                "warn",
                "warned",
                reason="Flooding",
                extra_note=(
                    f"You sent {limit}+ messages in a row in <b>{html_escape(GROUP_NAME)}</b>. "
                    f"You are at {warn_count}/{WARN_THRESHOLD} warnings; reaching "
                    f"{WARN_THRESHOLD} results in an automatic 1-hour mute."
                ),
            )
        return

    mute_seconds = _SPAM_CONFIG.get("mute_seconds", SPAM_MUTE_SECONDS)
    until_date = datetime.now(timezone.utc) + timedelta(seconds=mute_seconds)
    try:
        await context.bot.restrict_chat_member(
            GROUP_ID, user.id, permissions=ChatPermissions(can_send_messages=False), until_date=until_date
        )
    except Exception as e:
        await notify_devs(context, "antiflood: restrict_chat_member", e)
        return
    await _delete_flood_messages(context, message_ids)
    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'mute', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, user.id, f"Flooding ({limit}+ messages in a row, auto-detected)", None, now_iso()),
    )
    conn.commit()
    conn.close()
    try:
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('mute')} {html_escape(target_name)} has been auto-muted for "
            f"{format_duration(mute_seconds)} — flooding ({limit}+ messages in a row).",
            parse_mode="HTML",
        )
    except Exception as e:
        await notify_devs(context, "antiflood: announcement", e)
    await send_moderation_dm(
        context, user.id, "mute", "muted",
        extra_note=(
            f"You sent {limit}+ messages in a row in <b>{html_escape(GROUP_NAME)}</b> and were "
            f"automatically muted for {format_duration(mute_seconds)}.\n\n"
            "If you think this was a mistake, use /start in this chat and choose \"Appeal Mute/Ban\"."
        ),
    )
    if context.job_queue is not None:
        context.job_queue.run_once(_mute_expired_job, when=mute_seconds, data={"target_id": user.id})



_FLOOD_CONTENT_ATTRS = (
    "text", "caption", "photo", "video", "animation", "sticker", "voice",
    "video_note", "document", "audio", "poll", "dice", "game", "venue",
    "location", "contact",
)


def _has_user_content(msg) -> bool:
    """True if msg is a real, user-authored message (text/media/etc.) rather
    than a service notification (member tag changed, pinned message, chat
    title changed, ...). Service messages have no content fields set but
    still have from_user, so without this check something like /title's
    "member tag changed" notice gets miscounted as the target user having
    sent a message — tipping them into a flood warning/mute they didn't
    earn."""
    return any(getattr(msg, attr, None) for attr in _FLOOD_CONTENT_ATTRS)


async def check_flood(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not _SPAM_CONFIG["enabled"]:
        return
    msg = update.effective_message
    if not msg or not msg.from_user or msg.from_user.is_bot:
        return
    if not _has_user_content(msg):
        return  # service notification, not something the user actually sent
    user = msg.from_user
    if await is_authorized(context, user.id):
        return  # admins are exempt — they enforce this, they're not subject to it
    if is_approved(user.id):
        return  # explicitly approved via /free — passive detectors leave them alone

    now = time.monotonic()
    if _FLOOD_STATE["user_id"] == user.id and (now - _FLOOD_STATE["last_time"]) <= FLOOD_WINDOW_SECONDS:
        _FLOOD_STATE["count"] += 1
        _FLOOD_STATE["message_ids"].append(msg.message_id)
    else:
        _FLOOD_STATE["user_id"] = user.id
        _FLOOD_STATE["count"] = 1
        _FLOOD_STATE["message_ids"] = [msg.message_id]
    _FLOOD_STATE["last_time"] = now

    if _FLOOD_STATE["count"] >= _SPAM_CONFIG["limit"]:
        message_ids = list(_FLOOD_STATE["message_ids"])
        _FLOOD_STATE["count"] = 0
        _FLOOD_STATE["user_id"] = None
        _FLOOD_STATE["message_ids"] = []
        await _handle_flood_violation(context, user, message_ids=message_ids)


def _canonical_lock_type(raw: str):
    value = raw.strip().lower().replace("-", "_")
    return LOCK_TYPE_ALIASES.get(value, value)


def _lock_usage_text():
    return (
        "<b>Permission locks</b>\n\n"
        "<code>/lock media</code> — block photos, videos, files, audio, and voice/video notes\n"
        "<code>/lock stickers</code> — block stickers and GIFs\n"
        "<code>/lock photos|videos|files|audio|voice|video_notes|polls|reactions|messages</code>\n"
        "<code>/unlock &lt;type&gt;</code> — restore that permission\n"
        "<code>/locks</code> — show active locks\n\n"
        "Links are not included because Telegram cannot block URL text through permissions."
    )


async def _set_content_lock(update: Update, context: ContextTypes.DEFAULT_TYPE, enabled: bool):
    actor = update.effective_user
    if not actor or not await is_authorized(context, actor.id, "can_delete_messages", update=update):
        await deny_not_authorized(update, context)
        return
    if not context.args:
        await safe_reply(update, context, _lock_usage_text(), parse_mode="HTML")
        return

    lock_type = _canonical_lock_type(context.args[0])
    if lock_type == "all":
        types = list(LOCKABLE_TYPES)
    elif lock_type in LOCK_PERMISSION_FIELDS:
        types = [lock_type]
    else:
        await safe_reply(update, context, f"Unknown lock type <code>{html_escape(context.args[0])}</code>.\n\n{_lock_usage_text()}", parse_mode="HTML")
        return

    for item in types:
        set_setting(f"lock_{item}", "1" if enabled else "0")

    try:
        chat = await context.bot.get_chat(GROUP_ID)
        current = getattr(chat, "permissions", None)
        permission_fields = (
            "can_send_messages", "can_send_audios", "can_send_documents", "can_send_photos",
            "can_send_videos", "can_send_video_notes", "can_send_voice_notes", "can_send_polls",
            "can_send_other_messages", "can_add_web_page_previews", "can_react_to_messages",
        )
        values = {field: bool(getattr(current, field, True)) if current is not None else True for field in permission_fields}
        values["can_add_web_page_previews"] = False
        for fields in LOCK_PERMISSION_FIELDS.values():
            for field in fields:
                values[field] = True
        for active_type, fields in LOCK_PERMISSION_FIELDS.items():
            if get_setting(f"lock_{active_type}", "0") == "1":
                for field in fields:
                    values[field] = False
        await context.bot.set_chat_permissions(
            chat_id=GROUP_ID,
            permissions=ChatPermissions(**values),
            use_independent_chat_permissions=True,
        )
    except Exception as exc:
        for item in types:
            set_setting(f"lock_{item}", "0")
        await notify_devs(context, "content lock: set_chat_permissions", exc)
        await safe_reply(update, context, f"{pemoji('error')} I couldn't update group permissions. Make sure I have <b>Restrict Members</b> permission.", parse_mode="HTML")
        return

    label = ", ".join(types)
    action = "locked" if enabled else "unlocked"
    await safe_reply(update, context, f"{pemoji('approve')} <b>{html_escape(label.title())}</b> {action}.", parse_mode="HTML")


async def cmd_lock(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _set_content_lock(update, context, True)


async def cmd_unlock(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _set_content_lock(update, context, False)


async def cmd_locks(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not actor or not await is_authorized(context, actor.id, "can_delete_messages", update=update):
        await deny_not_authorized(update, context)
        return
    active = [item for item in LOCKABLE_TYPES if get_setting(f"lock_{item}", "0") == "1"]
    if not active:
        await safe_reply(update, context, "<b>Active permission locks</b>\nNone.", parse_mode="HTML")
        return
    await safe_reply(update, context, "<b>Active permission locks</b>\n" + "\n".join(f"• {html_escape(item)}" for item in active), parse_mode="HTML")


async def cmd_autoapprove(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global _AUTO_APPROVE_JOIN_REQUESTS
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_invite_users", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)
    if len(context.args) != 1 or context.args[0].lower() not in {"on", "off"}:
        state = "ON" if _AUTO_APPROVE_JOIN_REQUESTS else "OFF"
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('usage')} Auto-approve is currently <b>{state}</b>. "
            "Use <code>/autoapprove on</code> or <code>/autoapprove off</code>.",
            parse_mode="HTML",
        )
        return
    enabled = context.args[0].lower() == "on"
    _AUTO_APPROVE_JOIN_REQUESTS = enabled
    set_setting("autoapprove_join_requests", "1" if enabled else "0")
    status = "ON — new join requests will be approved automatically" if enabled else "OFF — admins must approve join requests manually"
    await context.bot.send_message(GROUP_ID, f"{pemoji('approve')} Auto-approve is now <b>{status}</b>.", parse_mode="HTML")


async def cmd_spam(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)
    if not context.args:
        enabled = "ON" if _SPAM_CONFIG["enabled"] else "OFF"
        action = _SPAM_CONFIG.get("action", "mute")
        action_text = (
            f"warnings only" if action == "warn"
            else f"mutes for {format_duration(_SPAM_CONFIG.get('mute_seconds', SPAM_MUTE_SECONDS))}"
        )
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('warn')} Anti-spam is <b>{enabled}</b>: "
            f"limit {_SPAM_CONFIG['limit']} messages in a row; {action_text}.",
            parse_mode="HTML",
        )
        return
    arg = context.args[0].lower()
    if arg == "off":
        _SPAM_CONFIG["enabled"] = False
        set_setting("spam_enabled", "0")
        await context.bot.send_message(
            GROUP_ID, f"{pemoji('warn')} Anti-spam is now <b>OFF</b>.", parse_mode="HTML"
        )
        return
    if arg == "on":
        _SPAM_CONFIG["enabled"] = True
        set_setting("spam_enabled", "1")
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('warn')} Anti-spam is now <b>ON</b> — limit "
            f"{_SPAM_CONFIG['limit']} messages; {_SPAM_CONFIG.get('action', 'mute')} mode.",
            parse_mode="HTML",
        )
        return
    if arg == "warn" and len(context.args) == 1:
        _SPAM_CONFIG["action"] = "warn"
        _SPAM_CONFIG["enabled"] = True
        set_setting("spam_enabled", "1")
        set_setting("spam_action", "warn")
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('warn')} Anti-spam enforcement set to <b>warning-only</b>. "
            f"Limit: {_SPAM_CONFIG['limit']} messages in a row.",
            parse_mode="HTML",
        )
        return
    if arg == "mute":
        if len(context.args) != 2:
            await safe_reply(update, context, 
                f"{pemoji('usage')} Use <code>/spam mute 1h</code>, <code>/spam mute 30m</code>, "
                "or another duration using s, m, h, d, or w.",
                parse_mode="HTML",
            )
            return
        mute_seconds, remainder = parse_duration(context.args[1])
        if mute_seconds is None or remainder or mute_seconds < 1:
            await safe_reply(update, context, 
                f"{pemoji('usage')} Invalid duration. Examples: <code>30m</code>, <code>1h</code>, <code>2d</code>.",
                parse_mode="HTML",
            )
            return
        _SPAM_CONFIG["action"] = "mute"
        _SPAM_CONFIG["enabled"] = True
        _SPAM_CONFIG["mute_seconds"] = mute_seconds
        set_setting("spam_action", "mute")
        set_setting("spam_mute_seconds", str(mute_seconds))
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('mute')} Anti-spam enforcement set to <b>mute</b> for "
            f"{format_duration(mute_seconds)}. Limit: {_SPAM_CONFIG['limit']} messages in a row.",
            parse_mode="HTML",
        )
        return
    if arg.isdigit() and int(arg) >= 2:
        _SPAM_CONFIG["limit"] = int(arg)
        _SPAM_CONFIG["enabled"] = True
        set_setting("spam_limit", arg)
        set_setting("spam_enabled", "1")
        await context.bot.send_message(
            GROUP_ID,
            f"{pemoji('warn')} Anti-spam limit set to <b>{arg}</b> messages in a row; "
            f"mode: {_SPAM_CONFIG.get('action', 'mute')}.",
            parse_mode="HTML",
        )
        return
    await safe_reply(update, context, 
        f"{pemoji('usage')} Usage:\n"
        "• <code>/spam N</code> — enable and set the limit to N messages in a row (min 2)\n"
        "• <code>/spam off</code> — disable anti-spam\n"
        "• <code>/spam on</code> — enable anti-spam\n"
        "• <code>/spam mute 1h</code> — mute violators for the chosen duration\n"
        "• <code>/spam warn</code> — warn violators without muting\n"
        "• <code>/spam</code> — show the current setting",
        parse_mode="HTML",
    )



# ---------------------------------------------------------------------------
# /unmuteall, /unbanall — deliberately locked to the fixed ADMIN_IDS list
# only (NOT the dynamic Telegram-group-admin permission system every other
# command uses). Requires confirmation via a red inline button that only
# the admin who ran the command can tap — anyone else tapping it gets an
# alert, not the action.
# ---------------------------------------------------------------------------
async def _bulk_unmute_or_unban_counts(action_type: str) -> int:
    conn = get_conn()
    row = conn.execute(
        "SELECT COUNT(DISTINCT user_id) AS c FROM moderation_actions "
        "WHERE chat_id = ? AND action = ? AND status = 'active'",
        (GROUP_ID, action_type),
    ).fetchone()
    conn.close()
    return row["c"]


async def cmd_unmuteall(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if actor.id not in ADMIN_IDS:
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    count = await _bulk_unmute_or_unban_counts("mute")
    if count == 0:
        await context.bot.send_message(
            GROUP_ID, f"{pemoji('mute')} Nobody is currently muted.", parse_mode="HTML"
        )
        return

    await context.bot.send_message(
        GROUP_ID,
        f"{pemoji('warn')} This will unmute all {count} currently muted member(s). Confirm?",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(
            [[InlineKeyboardButton("Confirm Unmute All", callback_data=f"bulkact_unmuteall_{actor.id}", style="danger")]]
        ),
    )


async def cmd_unbanall(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if actor.id not in ADMIN_IDS:
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    count = await _bulk_unmute_or_unban_counts("ban")
    if count == 0:
        await context.bot.send_message(
            GROUP_ID, f"{pemoji('ban')} Nobody is currently banned.", parse_mode="HTML"
        )
        return

    await context.bot.send_message(
        GROUP_ID,
        f"{pemoji('warn')} This will unban all {count} currently banned member(s). Confirm?",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(
            [[InlineKeyboardButton("Confirm Unban All", callback_data=f"bulkact_unbanall_{actor.id}", style="danger")]]
        ),
    )


async def handle_bulk_action(query, context: ContextTypes.DEFAULT_TYPE, data: str):
    parts = data.split("_")
    action = parts[1]  # "unmuteall" or "unbanall"
    owner_id = int(parts[2])

    if query.from_user.id != owner_id:
        await query.answer("This confirmation isn't for you.", show_alert=True)
        return

    await query.answer()
    try:
        await query.edit_message_reply_markup(reply_markup=None)  # can't be double-tapped
    except Exception:
        pass

    action_type = "mute" if action == "unmuteall" else "ban"
    conn = get_conn()
    rows = conn.execute(
        "SELECT DISTINCT user_id FROM moderation_actions WHERE chat_id = ? AND action = ? AND status = 'active'",
        (GROUP_ID, action_type),
    ).fetchall()
    conn.close()

    success = 0
    failed = 0
    for row in rows:
        uid = row["user_id"]
        try:
            if action == "unmuteall":
                await context.bot.restrict_chat_member(GROUP_ID, uid, permissions=FULL_PERMISSIONS)
            else:
                await context.bot.unban_chat_member(GROUP_ID, uid, only_if_banned=True)
            success += 1
        except Exception:
            failed += 1
        await asyncio.sleep(0.05)  # stay well under flood limits, same pacing as /purge

    conn = get_conn()
    conn.execute(
        "UPDATE moderation_actions SET status = 'lifted' WHERE chat_id = ? AND action = ? AND status = 'active'",
        (GROUP_ID, action_type),
    )
    conn.commit()
    conn.close()

    verb = "Unmuted" if action == "unmuteall" else "Unbanned"
    await context.bot.send_message(
        GROUP_ID,
        f"{pemoji('approve')} {verb} {success} member(s)." + (f" ({failed} failed — see dev alerts)" if failed else ""),
        parse_mode="HTML",
    )


async def cmd_unmute(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, _ = await _resolve_target_from_reply_or_args(update, context, tag_follows=False)
    if target_id is None:
        await safe_reply(update, context, 
            f"{pemoji('usage')} Usage:\n"
            "• Reply to their message with <code>/unmute</code>\n"
            "• Or <code>/unmute @username</code>",
            parse_mode="HTML",
        )
        return

    try:
        await context.bot.restrict_chat_member(GROUP_ID, target_id, permissions=FULL_PERMISSIONS)
    except Exception as e:
        await notify_devs(context, "cmd_unmute: restrict_chat_member", e)
        await safe_reply(update, context, 
            f"{pemoji('error')} Couldn't unmute {html_escape(target_name)}: {friendly_error(e)}",
            parse_mode="HTML",
        )
        return

    conn = get_conn()
    conn.execute(
        "UPDATE moderation_actions SET status = 'lifted' WHERE user_id = ? AND action = 'mute' AND status = 'active'",
        (target_id,),
    )
    conn.commit()
    conn.close()

    await safe_reply(update, context, 
        f"{pemoji('unmute')} {html_escape(target_name)} has been unmuted.",
        parse_mode="HTML",
    )
    await send_moderation_dm(context, target_id, "mute", "unmuted")


async def _do_ban(update: Update, context: ContextTypes.DEFAULT_TYPE, *, require_duration: bool):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, remainder = await _resolve_target_from_reply_or_args(update, context, tag_follows=True)
    if target_id is None:
        if require_duration:
            await safe_reply(update, context, 
                f"{pemoji('usage')} Usage:\n"
                "• Reply to their message with <code>/tempban [duration] &lt;reason&gt;</code>\n"
                "• Or <code>/tempban @username [duration] &lt;reason&gt;</code>\n\n"
                f"Duration is optional here too (e.g. <code>30m</code>, <code>2h</code>, <code>1d</code>, <code>1w</code>) — "
                f"leave it out and it defaults to {format_duration(TEMPBAN_DEFAULT_SECONDS)}.\n"
                "Example: <code>/tempban @user 1d repeated spam</code>",
                parse_mode="HTML",
            )
        else:
            await safe_reply(update, context, 
                f"{pemoji('usage')} Usage:\n"
                "• Reply to their message with <code>/ban &lt;reason&gt;</code>\n"
                "• Or <code>/ban @username &lt;reason&gt;</code>",
                parse_mode="HTML",
            )
        return

    if target_id in ADMIN_IDS or await is_authorized(context, target_id):
        await safe_reply(update, context, 
            f"{pemoji('error')} 😂 Are you blind? {html_escape(target_name)} is an admin — you can't ban them. Nice try though.",
            parse_mode="HTML",
        )
        return

    duration_seconds, reason = (None, remainder)
    if require_duration:
        duration_seconds, reason = parse_duration(remainder)
        if not duration_seconds:
            # /tban or /tempban with no duration given — default rather than error.
            duration_seconds = TEMPBAN_DEFAULT_SECONDS
        elif duration_seconds < 60:
            await safe_reply(update, context, 
                f"{pemoji('error')} Telegram treats bans under a minute as permanent — use at least <code>1m</code>.",
                parse_mode="HTML",
            )
            return

    reason = reason.strip() or None

    until_date = None
    if duration_seconds:
        until_date = datetime.now(timezone.utc) + timedelta(seconds=duration_seconds)

    try:
        await context.bot.ban_chat_member(GROUP_ID, target_id, until_date=until_date)
    except Exception as e:
        await notify_devs(context, "cmd_ban: ban_chat_member", e)
        await safe_reply(update, context, 
            f"{pemoji('error')} Couldn't ban {html_escape(target_name)}: {friendly_error(e)}",
            parse_mode="HTML",
        )
        return

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'ban', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, target_id, reason, actor.id, now_iso()),
    )
    conn.commit()
    conn.close()

    duration_note = f" for {format_duration(duration_seconds)}" if duration_seconds else ""
    await safe_reply(update, context, 
        f"{pemoji('ban')} {html_escape(target_name)} has been banned{duration_note}."
        + (f" Reason: {html_escape(reason)}" if reason else ""),
        parse_mode="HTML",
        reply_markup=_quick_unban_markup(target_id),
    )

    extra_note = (
        f"This ban lifts automatically in {format_duration(duration_seconds)}.\n\n"
        if duration_seconds
        else ""
    )
    extra_note += "If you think this was a mistake, use /start in this chat and choose \"Appeal Mute/Ban\"."
    await send_moderation_dm(context, target_id, "ban", "banned from", reason=reason, extra_note=extra_note)

    if duration_seconds and context.job_queue is not None:
        context.job_queue.run_once(
            _ban_expired_job, when=duration_seconds, data={"target_id": target_id}
        )


async def _ban_expired_job(context: ContextTypes.DEFAULT_TYPE):
    """Fires when a timed /tempban's duration elapses. Telegram itself
    already lifts the ban (we passed until_date), this just keeps the DB
    and the user in the loop."""
    target_id = context.job.data["target_id"]
    conn = get_conn()
    conn.execute(
        "UPDATE moderation_actions SET status = 'lifted' "
        "WHERE user_id = ? AND action = 'ban' AND status = 'active'",
        (target_id,),
    )
    conn.commit()
    conn.close()
    try:
        await context.bot.send_message(
            target_id,
            f"{pemoji('ban')} Your ban in <b>{html_escape(GROUP_NAME)}</b> has expired — "
            "you're welcome to rejoin.",
            parse_mode="HTML",
        )
    except Exception:
        pass


async def cmd_ban(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _do_ban(update, context, require_duration=False)


async def cmd_tempban(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await _do_ban(update, context, require_duration=True)


# ---------------------------------------------------------------------------
# /smute, /sban — silent versions of /mute and /ban. No group announcement,
# no reply to the admin on success — the only trace is the admin's own
# command message, which gets deleted immediately (not the ~1s delayed
# deletion the non-silent commands use, since there's no confirmation reply
# racing against it here). Errors and usage help still get a reply — those
# aren't a "confirmation of success", they're necessary feedback, and the
# admin's command message is left in place in that case so they can see
# what they typed.
# ---------------------------------------------------------------------------
async def cmd_smute(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return

    target_id, target_name, remainder = await _resolve_target_from_reply_or_args(update, context, tag_follows=True)
    if target_id is None:
        await safe_reply(
            update, context,
            f"{pemoji('usage')} Usage:\n"
            "• Reply to their message with <code>/smute [duration] &lt;reason&gt;</code>\n"
            "• Or <code>/smute @username [duration] &lt;reason&gt;</code>\n\n"
            "Same as /mute, but silent — no group announcement, no confirmation reply. "
            "Duration is optional (e.g. <code>30m</code>, <code>2h</code>, <code>1d</code>).",
            parse_mode="HTML",
        )
        return

    if target_id in ADMIN_IDS or await is_authorized(context, target_id):
        await safe_reply(
            update, context,
            f"{pemoji('error')} 😂 Are you blind? {html_escape(target_name)} is an admin — you can't mute them. Nice try though.",
            parse_mode="HTML",
        )
        return

    duration_seconds, reason = parse_duration(remainder)
    reason = reason.strip() or None
    until_date = datetime.now(timezone.utc) + timedelta(seconds=duration_seconds) if duration_seconds else None

    try:
        await context.bot.restrict_chat_member(
            GROUP_ID, target_id, permissions=ChatPermissions(can_send_messages=False), until_date=until_date
        )
    except Exception as e:
        await notify_devs(context, "cmd_smute: restrict_chat_member", e)
        await safe_reply(
            update, context,
            f"{pemoji('error')} Couldn't mute {html_escape(target_name)}: {friendly_error(e)}",
            parse_mode="HTML",
        )
        return

    # Success — delete the admin's command message immediately (no reply
    # follows, so no need for the delayed-deletion job) and stay silent.
    msg = update.message
    if msg is not None and msg.chat_id == GROUP_ID:
        try:
            await context.bot.delete_message(GROUP_ID, msg.message_id)
        except Exception as e:
            await notify_devs(context, "cmd_smute: delete_message", e)

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'mute', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, target_id, reason, actor.id, now_iso()),
    )
    conn.commit()
    conn.close()

    extra_note = (
        f"This mute lifts automatically in {format_duration(duration_seconds)}.\n\n"
        if duration_seconds
        else ""
    )
    extra_note += (
        "If you think this was a mistake, use /start in this chat and choose "
        "\"Appeal Mute/Ban\"."
    )
    await send_moderation_dm(context, target_id, "mute", "muted", reason=reason, extra_note=extra_note)

    if duration_seconds and context.job_queue is not None:
        context.job_queue.run_once(
            _mute_expired_job, when=duration_seconds, data={"target_id": target_id}
        )


