# ---------------------------------------------------------------------------
# /free (alias /approve), /unfree (alias /unapprove) — exempt or restore a
# member for passive moderation detectors only. Manual commands still work.
# ---------------------------------------------------------------------------
async def cmd_free(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, _ = await _resolve_target_from_reply_or_args(update, context, tag_follows=False)
    if target_id is None:
        await safe_reply(
            update, context,
            f"{pemoji('usage')} Usage:\n"
            "• Reply to their message with <code>/free</code>\n"
            "• Or <code>/free @username</code> / <code>/free &lt;UserID&gt;</code>\n\n"
            "Exempts them from automatic moderation (blacklist, NSFW detection, anti-flood, "
            "blocked stickers). Manual admin commands still work on them as normal.",
            parse_mode="HTML",
        )
        return

    if target_id in _APPROVED_USERS_CACHE:
        await safe_reply(update, context,
            f"{pemoji('approve')} {html_escape(target_name)} is already approved.", parse_mode="HTML"
        )
        return

    conn = get_conn()
    conn.execute(
        "INSERT OR REPLACE INTO approved_users (user_id, approved_by, approved_at) VALUES (?, ?, ?)",
        (target_id, actor.id, now_iso()),
    )
    conn.commit()
    conn.close()
    _APPROVED_USERS_CACHE.add(target_id)

    await safe_reply(
        update, context,
        f"{pemoji('approve')} {html_escape(target_name)} is now approved — the bot's automatic "
        "moderation (blacklist, NSFW detection, anti-flood, blocked stickers) won't act against "
        "them. Manual mod commands still work on them as normal.",
        parse_mode="HTML",
    )


async def cmd_unfree(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, _ = await _resolve_target_from_reply_or_args(update, context, tag_follows=False)
    if target_id is None:
        await safe_reply(
            update, context,
            f"{pemoji('usage')} Usage:\n"
            "• Reply to their message with <code>/unfree</code>\n"
            "• Or <code>/unfree @username</code> / <code>/unfree &lt;UserID&gt;</code>",
            parse_mode="HTML",
        )
        return

    if target_id not in _APPROVED_USERS_CACHE:
        await safe_reply(update, context,
            f"{pemoji('warn')} {html_escape(target_name)} isn't currently approved.", parse_mode="HTML"
        )
        return

    conn = get_conn()
    conn.execute("DELETE FROM approved_users WHERE user_id = ?", (target_id,))
    conn.commit()
    conn.close()
    _APPROVED_USERS_CACHE.discard(target_id)

    await safe_reply(
        update, context,
        f"{pemoji('reject')} {html_escape(target_name)} is no longer approved — automatic "
        "moderation applies to them again.",
        parse_mode="HTML",
    )


# ---------------------------------------------------------------------------
# Quick unmute/unban buttons — attached to every mute/ban confirmation
# message (whichever command produced it: /mute, /tempmute, /dmute, the
# warn-threshold auto-mute, /ban, /tempban, /dban, ...). Any admin with
# can_restrict_members can tap it; the button then disappears and the
# message is edited in place to show the result.
# ---------------------------------------------------------------------------
def _quick_unmute_markup(target_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        [[InlineKeyboardButton("🔈 Unmute", callback_data=f"quickunmute_{target_id}", style="primary")]]
    )


def _quick_unban_markup(target_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        [[InlineKeyboardButton("🔒 Unban", callback_data=f"quickunban_{target_id}", style="primary")]]
    )


def _known_display_name(user_id: int) -> str:
    """Best-effort display name for a user_id from our own cache — used
    when editing a quick-unmute/unban button message, since callback_data
    only carries the target_id (Telegram caps it at 64 bytes)."""
    conn = get_conn()
    row = conn.execute(
        "SELECT username, full_name FROM known_users WHERE user_id = ?", (user_id,)
    ).fetchone()
    conn.close()
    if row and row["username"]:
        return f"@{row['username']}"
    if row and row["full_name"]:
        return html_escape(row["full_name"])
    return f"User {user_id}"


async def _quick_unmute(context: ContextTypes.DEFAULT_TYPE, target_id: int):
    """Performs the actual unmute + DB update. Returns (ok, error_text)."""
    try:
        await context.bot.restrict_chat_member(GROUP_ID, target_id, permissions=FULL_PERMISSIONS)
    except Exception as e:
        await notify_devs(context, "quick unmute button: restrict_chat_member", e)
        return False, str(e)

    conn = get_conn()
    conn.execute(
        "UPDATE moderation_actions SET status = 'lifted' WHERE user_id = ? AND action = 'mute' AND status = 'active'",
        (target_id,),
    )
    conn.commit()
    conn.close()
    await send_moderation_dm(context, target_id, "mute", "unmuted")
    return True, None


async def _quick_unban(context: ContextTypes.DEFAULT_TYPE, target_id: int):
    """Performs the actual unban + DB update. Returns (ok, error_text)."""
    try:
        await context.bot.unban_chat_member(GROUP_ID, target_id, only_if_banned=True)
    except Exception as e:
        await notify_devs(context, "quick unban button: unban_chat_member", e)
        return False, str(e)

    conn = get_conn()
    conn.execute(
        "UPDATE moderation_actions SET status = 'lifted' WHERE user_id = ? AND action = 'ban' AND status = 'active'",
        (target_id,),
    )
    conn.commit()
    conn.close()
    await send_moderation_dm(context, target_id, "ban", "unbanned from")
    return True, None


async def handle_quick_unmute_unban(query, context: ContextTypes.DEFAULT_TYPE, data: str):
    admin = query.from_user
    if not await is_authorized(context, admin.id, "can_restrict_members"):
        await query.answer("You are not authorized for this action.", show_alert=True)
        return

    is_unmute = data.startswith("quickunmute_")
    target_id = int(data[len("quickunmute_"):] if is_unmute else data[len("quickunban_"):])
    target_name = _known_display_name(target_id)

    ok, err = await (_quick_unmute(context, target_id) if is_unmute else _quick_unban(context, target_id))
    if not ok:
        action_word = "unmute" if is_unmute else "unban"
        await query.answer(f"Couldn't {action_word}: {err}", show_alert=True)
        return

    admin_mention = f"@{admin.username}" if admin.username else html_escape(admin.full_name)
    verb = "unmuted" if is_unmute else "unbanned"
    emoji_key = "unmute" if is_unmute else "lock"
    try:
        # No reply_markup here — that's what makes the button disappear.
        await query.edit_message_text(
            f"{pemoji(emoji_key)} {target_name} has been {verb} by {admin_mention}.",
            parse_mode="HTML",
        )
    except Exception:
        pass
    await query.answer(f"User {verb}.")


async def cmd_warn(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, reason = await _resolve_target_from_reply_or_args(update, context, tag_follows=True)
    if target_id is None:
        await safe_reply(update, context, 
            f"{pemoji('usage')} Usage:\n"
            "• Reply to their message with <code>/warn &lt;reason&gt;</code>\n"
            "• Or <code>/warn @username &lt;reason&gt;</code>",
            parse_mode="HTML",
        )
        return

    if target_id in ADMIN_IDS or await is_authorized(context, target_id):
        await safe_reply(update, context, 
            f"{pemoji('error')} 😂 Are you blind? {html_escape(target_name)} is an admin — you can't warn them. Nice try though.",
            parse_mode="HTML",
        )
        return

    reason = reason.strip() or None

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'warn', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, target_id, reason, actor.id, now_iso()),
    )
    conn.commit()
    warn_count = conn.execute(
        "SELECT COUNT(*) AS c FROM moderation_actions WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
        (GROUP_ID, target_id),
    ).fetchone()["c"]
    conn.close()

    await safe_reply(update, context, 
        f"{pemoji('warn')} {html_escape(target_name)} has been warned ({warn_count}/{WARN_THRESHOLD})."
        + (f" Reason: {html_escape(reason)}" if reason else ""),
        parse_mode="HTML",
    )

    if warn_count >= WARN_THRESHOLD:
        # Auto-escalate to a timed mute, and reset the warning count.
        until_date = datetime.now(timezone.utc) + timedelta(seconds=WARN_AUTO_MUTE_SECONDS)
        try:
            await context.bot.restrict_chat_member(
                GROUP_ID, target_id, permissions=ChatPermissions(can_send_messages=False), until_date=until_date
            )
            conn = get_conn()
            conn.execute(
                "UPDATE moderation_actions SET status = 'lifted' WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
                (GROUP_ID, target_id),
            )
            conn.execute(
                "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
                "VALUES (?, ?, ?, 'mute', ?, ?, ?, 'active')",
                (GROUP_ID, GROUP_NAME, target_id, f"Auto-mute: reached {WARN_THRESHOLD} warnings", actor.id, now_iso()),
            )
            conn.commit()
            conn.close()

            await safe_reply(update, context, 
                f"{pemoji('mute')} {html_escape(target_name)} reached {WARN_THRESHOLD} warnings and has been auto-muted "
                f"for {format_duration(WARN_AUTO_MUTE_SECONDS)}.",
                parse_mode="HTML",
                reply_markup=_quick_unmute_markup(target_id),
            )
            await send_moderation_dm(
                context, target_id, "mute", "muted",
                extra_note=(
                    f"You reached {WARN_THRESHOLD} warnings in <b>{html_escape(GROUP_NAME)}</b> and were "
                    f"automatically muted for {format_duration(WARN_AUTO_MUTE_SECONDS)}.\n\n"
                    "If you think this was a mistake, use /start in this chat and choose "
                    "\"Appeal Mute/Ban\"."
                ),
            )
            if context.job_queue is not None:
                context.job_queue.run_once(
                    _mute_expired_job, when=WARN_AUTO_MUTE_SECONDS, data={"target_id": target_id}
                )
        except Exception as e:
            await notify_devs(context, "cmd_warn: auto-mute after threshold", e)
    else:
        await send_moderation_dm(
            context, target_id, "warn", "warned",
            reason=reason,
            extra_note=f"You are at {warn_count}/{WARN_THRESHOLD} warnings — reaching {WARN_THRESHOLD} results in an automatic mute.",
        )


async def cmd_resetwarn(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
