async def check_blacklisted_words(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.effective_message
    sender = update.effective_user
    if not msg or not msg.text or not sender:
        return

    conn = get_conn()
    words = [r["word"] for r in conn.execute("SELECT word FROM blacklisted_words").fetchall()]
    conn.close()
    if not words:
        return

    matched = _find_blacklisted_word(msg.text, words)
    if not matched:
        return

    # Admins are exempt — their message stays, no action taken.
    if sender.id in ADMIN_IDS or await is_authorized(context, sender.id) or is_approved(sender.id):
        return

    try:
        await context.bot.delete_message(GROUP_ID, msg.message_id)
    except Exception as e:
        await notify_devs(context, "check_blacklisted_words: delete_message", e)

    target_name = f"@{sender.username}" if sender.username else html_escape(sender.full_name)
    reason = f"Used blacklisted word: {matched}"

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'warn', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, sender.id, reason, context.bot.id, now_iso()),
    )
    conn.commit()
    warn_count = conn.execute(
        "SELECT COUNT(*) AS c FROM moderation_actions WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
        (GROUP_ID, sender.id),
    ).fetchone()["c"]
    conn.close()

    await context.bot.send_message(
        GROUP_ID,
        f"{pemoji('warn')} {target_name} has been warned for using a blacklisted word ({warn_count}/{WARN_THRESHOLD}).",
        parse_mode="HTML",
    )

    if warn_count >= WARN_THRESHOLD:
        # Same auto-mute escalation as /warn.
        until_date = datetime.now(timezone.utc) + timedelta(seconds=WARN_AUTO_MUTE_SECONDS)
        try:
            await context.bot.restrict_chat_member(
                GROUP_ID, sender.id, permissions=ChatPermissions(can_send_messages=False), until_date=until_date
            )
            conn = get_conn()
            conn.execute(
                "UPDATE moderation_actions SET status = 'lifted' WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
                (GROUP_ID, sender.id),
            )
            conn.execute(
                "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
                "VALUES (?, ?, ?, 'mute', ?, ?, ?, 'active')",
                (GROUP_ID, GROUP_NAME, sender.id, f"Auto-mute: reached {WARN_THRESHOLD} warnings", context.bot.id, now_iso()),
            )
            conn.commit()
            conn.close()

            await context.bot.send_message(
                GROUP_ID,
                f"{pemoji('mute')} {target_name} reached {WARN_THRESHOLD} warnings and has been auto-muted "
                f"for {format_duration(WARN_AUTO_MUTE_SECONDS)}.",
                parse_mode="HTML",
                reply_markup=_quick_unmute_markup(sender.id),
            )
            await send_moderation_dm(
                context, sender.id, "mute", "muted",
                extra_note=(
                    f"You reached {WARN_THRESHOLD} warnings in <b>{html_escape(GROUP_NAME)}</b> and were "
                    f"automatically muted for {format_duration(WARN_AUTO_MUTE_SECONDS)}.\n\n"
                    "If you think this was a mistake, use /start in this chat and choose "
                    "\"Appeal Mute/Ban\"."
                ),
            )
            if context.job_queue is not None:
                context.job_queue.run_once(
                    _mute_expired_job, when=WARN_AUTO_MUTE_SECONDS, data={"target_id": sender.id}
                )
        except Exception as e:
            await notify_devs(context, "check_blacklisted_words: auto-mute after threshold", e)
    else:
        await send_moderation_dm(
            context, sender.id, "warn", "warned",
            reason=reason,
            extra_note=f"You are at {warn_count}/{WARN_THRESHOLD} warnings — reaching {WARN_THRESHOLD} results in an automatic mute.",
        )


async def cmd_kick(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, reason = await _resolve_target_from_reply_or_args(update, context, tag_follows=True)
    if target_id is None:
        await safe_reply(update, context, 
            f"{pemoji('usage')} Usage:\n"
            "• Reply to their message with <code>/kick &lt;reason&gt;</code>\n"
            "• Or <code>/kick @username &lt;reason&gt;</code>\n\n"
            "Unlike /ban, a kick just removes them from the group — they can rejoin with a new invite link.",
            parse_mode="HTML",
        )
        return

    if target_id in ADMIN_IDS or await is_authorized(context, target_id):
        await safe_reply(update, context, 
            f"{pemoji('error')} 😂 Are you blind? {html_escape(target_name)} is an admin — you can't kick them. Nice try though.",
            parse_mode="HTML",
        )
        return

    reason = reason.strip() or None

    try:
        # There's no dedicated "kick" API — ban then immediately unban, which
        # removes the member without leaving a standing ban behind.
        await context.bot.ban_chat_member(GROUP_ID, target_id)
        await context.bot.unban_chat_member(GROUP_ID, target_id, only_if_banned=True)
    except Exception as e:
        await notify_devs(context, "cmd_kick: ban/unban_chat_member", e)
        await safe_reply(update, context, 
            f"{pemoji('error')} Couldn't kick {html_escape(target_name)}: {friendly_error(e)}",
            parse_mode="HTML",
        )
        return

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'kick', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, target_id, reason, actor.id, now_iso()),
    )
    conn.commit()
    conn.close()

    await safe_reply(update, context, 
        f"{pemoji('hammer')} {html_escape(target_name)} has been kicked."
        + (f" Reason: {html_escape(reason)}" if reason else ""),
        parse_mode="HTML",
    )
    await send_moderation_dm(
        context, target_id, "hammer", "kicked from",
        reason=reason,
        extra_note="You're welcome to rejoin with a new invite link.",
    )


# ---------------------------------------------------------------------------
# /pin, /unpin — gated on the Telegram "Pin Messages" admin permission via
# is_authorized(), same dynamic-permission system as everything else.
# ---------------------------------------------------------------------------
async def cmd_pin(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_pin_messages", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    msg = update.message
    if not msg.reply_to_message:
        await safe_reply(update, context, 
            f"{pemoji('usage')} Reply to the message you want pinned with <code>/pin</code> "
            "(add <code>silent</code> to pin without notifying everyone, e.g. <code>/pin silent</code>).",
            parse_mode="HTML",
        )
        return

    silent = bool(context.args) and context.args[0].lower() in ("silent", "s", "quiet")

    try:
        await context.bot.pin_chat_message(
            GROUP_ID, msg.reply_to_message.message_id, disable_notification=silent
        )
    except Exception as e:
        await notify_devs(context, "cmd_pin: pin_chat_message", e)
        await safe_reply(update, context, 
            f"{pemoji('error')} Couldn't pin that message: {friendly_error(e)}", parse_mode="HTML"
        )
        return

    await safe_reply(update, context, f"{pemoji('pin')} Message pinned.", parse_mode="HTML")


async def cmd_unpin(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_pin_messages", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    msg = update.message
    unpin_all = bool(context.args) and context.args[0].lower() == "all"

    try:
        if unpin_all:
            await context.bot.unpin_all_chat_messages(GROUP_ID)
            await safe_reply(update, context, f"{pemoji('pin')} All pinned messages cleared.", parse_mode="HTML")
        elif msg.reply_to_message:
            await context.bot.unpin_chat_message(GROUP_ID, msg.reply_to_message.message_id)
            await safe_reply(update, context, f"{pemoji('pin')} Message unpinned.", parse_mode="HTML")
        else:
            # No reply given — unpins whatever is currently the most
            # recently pinned message, same as Telegram's own default.
            await context.bot.unpin_chat_message(GROUP_ID)
            await safe_reply(update, context, f"{pemoji('pin')} Most recent pinned message unpinned.", parse_mode="HTML")
    except Exception as e:
        await notify_devs(context, "cmd_unpin: unpin_chat_message", e)
        await safe_reply(update, context, 
            f"{pemoji('error')} Couldn't unpin: {friendly_error(e)}\n\n"
            "Usage: reply to a pinned message with <code>/unpin</code>, or use "
            "<code>/unpin</code> alone for the most recent pin, or <code>/unpin all</code> to clear every pin.",
            parse_mode="HTML",
        )


# ---------------------------------------------------------------------------
# /promote, /demote (aliases: /mod, /unmod) — gated on the Telegram
# "Add New Admins" permission. Grants a standard moderator preset (delete
# messages, restrict/ban members, pin messages, invite via link) — NOT the
# right to promote/demote others, so a promoted mod can't chain-promote.
# Promoted admins are picked up automatically by is_authorized() /
# _get_group_admin_map() — no bot restart needed.
# ---------------------------------------------------------------------------
async def cmd_promote(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_promote_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, title = await _resolve_target_from_reply_or_args(update, context, tag_follows=True)
    if target_id is None:
        await safe_reply(update, context, 
            f"{pemoji('usage')} Usage:\n"
            "• Reply to their message with <code>/promote [title]</code>\n"
            "• Or <code>/promote @username [title]</code> / <code>/promote &lt;UserID&gt; [title]</code>\n\n"
            "Grants a standard moderator role: delete messages, restrict/ban members, "
            "pin messages, invite via link. Doesn't grant the right to promote/demote others.\n\n"
            "Title is optional (max 16 characters) — what shows next to their name instead "
            "of the default \"admin\" label, e.g. <code>/promote @user Moderator</code>.",
            parse_mode="HTML",
        )
        return

    truncated = len(title) > TAG_MAX_LEN if title else False
    if truncated:
        title = title[:TAG_MAX_LEN]

    try:
        await context.bot.promote_chat_member(
            GROUP_ID, target_id,
            can_manage_chat=True,
            can_delete_messages=True,
            can_restrict_members=True,
            can_pin_messages=True,
            can_invite_users=True,
            can_change_info=False,
            can_promote_members=False,
            can_manage_video_chats=False,
            is_anonymous=False,
        )
    except Exception as e:
        await notify_devs(context, "cmd_promote: promote_chat_member", e)
        await safe_reply(update, context, 
            f"{pemoji('error')} Couldn't promote {html_escape(target_name)}: {friendly_error(e)}",
            parse_mode="HTML",
        )
        return

    title_failed = False
    if title:
        try:
            await context.bot.set_chat_administrator_custom_title(GROUP_ID, target_id, title)
        except Exception as e:
            title_failed = True
            await notify_devs(context, "cmd_promote: set_chat_administrator_custom_title", e)
            # The promotion itself already went through — don't fail the whole
            # command just because the title specifically couldn't be set.

    _GROUP_ADMIN_CACHE["expires"] = 0.0  # force a fresh admin list on the very next permission check

    confirmation = f"{pemoji('promote')} {html_escape(target_name)} has been promoted to admin"
    if title and not title_failed:
        confirmation += f" with the title \"{html_escape(title)}\""
        if truncated:
            confirmation += " (truncated to 16 characters)"
    confirmation += "."
    if title_failed:
        confirmation += " (Promoted, but couldn't set the custom title — Telegram rejected it.)"
    await safe_reply(update, context, confirmation, parse_mode="HTML")

    try:
        await context.bot.send_message(
            target_id,
            f"{pemoji('promote')} You've been promoted to admin in <b>{html_escape(GROUP_NAME)}</b>"
            + (f" as \"{html_escape(title)}\"" if title and not title_failed else "")
            + ". You can now use the bot's moderation commands according to your permissions.",
            parse_mode="HTML",
        )
    except Exception:
        pass


async def cmd_demote(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_promote_members", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    target_id, target_name, _ = await _resolve_target_from_reply_or_args(update, context, tag_follows=False)
    if target_id is None:
        await safe_reply(update, context, 
            f"{pemoji('usage')} Usage:\n"
            "• Reply to their message with <code>/demote</code>\n"
            "• Or <code>/demote @username</code> / <code>/demote &lt;UserID&gt;</code>",
            parse_mode="HTML",
        )
        return

    try:
        member = await context.bot.get_chat_member(GROUP_ID, target_id)
        if member.status == ChatMemberStatus.OWNER:
            await safe_reply(update, context, 
                f"{pemoji('error')} Can't demote the group creator.", parse_mode="HTML"
            )
            return
    except Exception:
        pass  # lookup failing isn't fatal — let promote_chat_member below surface the real error

    try:
        await context.bot.promote_chat_member(
            GROUP_ID, target_id,
            can_manage_chat=False,
            can_delete_messages=False,
            can_restrict_members=False,
            can_pin_messages=False,
            can_invite_users=False,
            can_change_info=False,
            can_promote_members=False,
            can_manage_video_chats=False,
            is_anonymous=False,
        )
    except Exception as e:
        await notify_devs(context, "cmd_demote: promote_chat_member", e)
        await safe_reply(update, context, 
            f"{pemoji('error')} Couldn't demote {html_escape(target_name)}: {friendly_error(e)}",
            parse_mode="HTML",
        )
        return

    _GROUP_ADMIN_CACHE["expires"] = 0.0

    note = (
        " (They're still in the bot's fixed admin list, so bot commands still work for them "
        "regardless of Telegram admin status.)" if target_id in ADMIN_IDS else ""
    )
    await safe_reply(update, context, 
        f"{pemoji('demote')} {html_escape(target_name)} has been demoted to a regular member.{note}",
        parse_mode="HTML",
    )
    try:
        await context.bot.send_message(
            target_id,
            f"{pemoji('demote')} You've been demoted from admin in <b>{html_escape(GROUP_NAME)}</b>.",
            parse_mode="HTML",
        )
    except Exception:
        pass


# ---------------------------------------------------------------------------
# "d"/"del" commands — delete the offending message AND the admin's own
# command message, take the action, and post a public announcement in the
# group (e.g. "⛔ @user banned by @admin / Reason: ..."). Always used as a
# reply to the message being actioned, since that's what tells the bot
# which message to delete. Both "d<action>" and "del<action>" work as
# aliases (e.g. /dban and /delban do the same thing) — same for "." "!" "*"
# prefixes via the alt-prefix system below.
# ---------------------------------------------------------------------------
_DELETE_ACTION_EMOJI = {"ban": "⛔", "mute": "🔇", "warn": "⚠️", "kick": "👢"}
_DELETE_ACTION_VERB = {"ban": "banned", "mute": "muted", "warn": "warned", "kick": "kicked"}
_DELETE_ACTION_DM_VERB = {"ban": "banned from", "mute": "muted", "warn": "warned", "kick": "kicked from"}
_DELETE_ACTION_EMOJI_KEY = {"ban": "ban", "mute": "mute", "warn": "warn", "kick": "hammer"}


async def _delete_and_act(update: Update, context: ContextTypes.DEFAULT_TYPE, action: str):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_restrict_members", update=update):
        await deny_not_authorized(update, context)
        return

    msg = update.message
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        duration_hint = (
            f" Duration is optional too (e.g. <code>30m</code>, <code>2h</code>, <code>1d</code>) — "
            f"put it right before the reason, e.g. <code>/d{action} 2h spamming links</code>."
            if action == "mute"
            else ""
        )
        await safe_reply(update, context, 
            f"{pemoji('usage')} Reply to the message you want deleted with <code>/d{action} &lt;reason&gt;</code> "
            f"(or <code>/del{action} &lt;reason&gt;</code>) to delete it and {action} the sender.{duration_hint}",
            parse_mode="HTML",
        )
        return

    target = msg.reply_to_message.from_user
    target_id = target.id
    remainder = " ".join(context.args).strip() if context.args else ""
    if action == "mute":
        # Only /dmute (not /dban, /dkick, /dwarn) takes a duration —
        # parse it the same way /mute and /tmute do.
        duration_seconds, reason = parse_duration(remainder)
        reason = reason.strip() or None
    else:
        duration_seconds = None
        reason = remainder or None

    target_mention = f"@{target.username}" if target.username else html_escape(target.full_name)
    actor_mention = f"@{actor.username}" if actor.username else html_escape(actor.full_name)

    if target_id in ADMIN_IDS or await is_authorized(context, target_id):
        await safe_reply(update, context, 
            f"{pemoji('error')} 😂 Are you blind? {target_mention} is an admin — you can't {action} them. Nice try though.",
            parse_mode="HTML",
        )
        return

    # Delete the offending message and the admin's own command message.
    for message_to_delete in (msg.reply_to_message, msg):
        try:
            await context.bot.delete_message(GROUP_ID, message_to_delete.message_id)
        except Exception as e:
            await notify_devs(context, f"_delete_and_act({action}): delete_message", e)

    try:
        if action == "ban":
            await context.bot.ban_chat_member(GROUP_ID, target_id)
        elif action == "mute":
            until_date = (
                datetime.now(timezone.utc) + timedelta(seconds=duration_seconds)
                if duration_seconds
                else None
            )
            await context.bot.restrict_chat_member(
                GROUP_ID, target_id, permissions=ChatPermissions(can_send_messages=False), until_date=until_date
            )
        elif action == "kick":
            # No dedicated "kick" API — ban then immediately unban.
            await context.bot.ban_chat_member(GROUP_ID, target_id)
            await context.bot.unban_chat_member(GROUP_ID, target_id, only_if_banned=True)
        # "warn" has no Telegram API call — just the DB write below.
    except Exception as e:
        await notify_devs(context, f"_delete_and_act({action}): telegram action", e)
        try:
            await context.bot.send_message(
                actor.id,
                f"{pemoji('error')} Deleted the message, but couldn't {action} {target_mention}: {friendly_error(e)}",
                parse_mode="HTML",
            )
        except Exception:
            pass
        return

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, target_id, action, reason, actor.id, now_iso()),
    )
    conn.commit()

    warn_count = None
    if action == "warn":
        warn_count = conn.execute(
            "SELECT COUNT(*) AS c FROM moderation_actions WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
            (GROUP_ID, target_id),
        ).fetchone()["c"]
    conn.close()

    announcement = (
        f"{pemoji(_DELETE_ACTION_EMOJI_KEY[action])} {target_mention} {_DELETE_ACTION_VERB[action]}"
        + (f" for {format_duration(duration_seconds)}" if action == "mute" and duration_seconds else "")
        + f" by {actor_mention}"
    )
    if action == "warn" and warn_count is not None:
        announcement += f" ({warn_count}/{WARN_THRESHOLD})"
    announcement += f"\nReason: {html_escape(reason) if reason else 'No reason given'}"

    quick_markup = None
    if action == "mute":
        quick_markup = _quick_unmute_markup(target_id)
    elif action == "ban":
        quick_markup = _quick_unban_markup(target_id)

    try:
        await context.bot.send_message(GROUP_ID, announcement, parse_mode="HTML", reply_markup=quick_markup)
    except Exception as e:
        await notify_devs(context, f"_delete_and_act({action}): announcement", e)

    extra_note = (
        "If you think this was a mistake, use /start in this chat and choose \"Appeal Mute/Ban\"."
        if action in ("ban", "mute", "kick")
        else f"You are at {warn_count}/{WARN_THRESHOLD} warnings — reaching {WARN_THRESHOLD} results in an automatic mute."
        if action == "warn"
        else ""
    )
    if action == "kick":
        extra_note = "You're welcome to rejoin with a new invite link."
    if action == "mute" and duration_seconds:
        extra_note = f"This mute lifts automatically in {format_duration(duration_seconds)}.\n\n" + extra_note

    await send_moderation_dm(
        context, target_id, _DELETE_ACTION_EMOJI_KEY[action], _DELETE_ACTION_DM_VERB[action],
        reason=reason, extra_note=extra_note,
    )

    if action == "mute" and duration_seconds and context.job_queue is not None:
        context.job_queue.run_once(
            _mute_expired_job, when=duration_seconds, data={"target_id": target_id}
        )


    # Same warn -> auto-mute escalation as /warn.
    if action == "warn" and warn_count is not None and warn_count >= WARN_THRESHOLD:
        until_date = datetime.now(timezone.utc) + timedelta(seconds=WARN_AUTO_MUTE_SECONDS)
        try:
            await context.bot.restrict_chat_member(
                GROUP_ID, target_id, permissions=ChatPermissions(can_send_messages=False), until_date=until_date
            )
            conn = get_conn()
            conn.execute(
                "UPDATE moderation_actions SET status = 'lifted' WHERE chat_id = ? AND user_id = ? AND action = 'warn' AND status = 'active'",
                (GROUP_ID, target_id),
            )
            conn.execute(
                "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
                "VALUES (?, ?, ?, 'mute', ?, ?, ?, 'active')",
                (GROUP_ID, GROUP_NAME, target_id, f"Auto-mute: reached {WARN_THRESHOLD} warnings", actor.id, now_iso()),
            )
            conn.commit()
            conn.close()

            await context.bot.send_message(
                GROUP_ID,
                f"{pemoji('mute')} {target_mention} reached {WARN_THRESHOLD} warnings and has been auto-muted "
                f"for {format_duration(WARN_AUTO_MUTE_SECONDS)}.",
                parse_mode="HTML",
                reply_markup=_quick_unmute_markup(target_id),
            )
            await send_moderation_dm(
                context, target_id, "mute", "muted",
                extra_note=(
                    f"You reached {WARN_THRESHOLD} warnings in <b>{html_escape(GROUP_NAME)}</b> and were "
                    f"automatically muted for {format_duration(WARN_AUTO_MUTE_SECONDS)}.\n\n"
                    "If you think this was a mistake, use /start in this chat and choose "
                    "\"Appeal Mute/Ban\"."
                ),
            )
            if context.job_queue is not None:
                context.job_queue.run_once(
                    _mute_expired_job, when=WARN_AUTO_MUTE_SECONDS, data={"target_id": target_id}
                )
        except Exception as e:
            await notify_devs(context, "_delete_and_act(warn): auto-mute after threshold", e)


