# ---------------------------------------------------------------------------
# /dblock (alias /delblock) — reply to a sticker to delete it and add it to
# the block list, so every future instance of that exact sticker gets
# silently deleted on sight (see check_blocked_sticker below). Unlike the
# other d*/del* commands, there's no args-based fallback — a sticker can
# only be identified by replying to one.
# ---------------------------------------------------------------------------
async def cmd_dblock(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_delete_messages", update=update):
        await deny_not_authorized(update, context)
        return
    msg = update.message
    replied = msg.reply_to_message
    if not replied or not replied.sticker:
        await safe_reply(update, context, 
            f"{pemoji('usage')} Reply to the sticker you want blocked with <code>/dblock [reason]</code> "
            "(or <code>/delblock [reason]</code>).",
            parse_mode="HTML",
        )
        return
    sticker = replied.sticker
    reason = " ".join(context.args).strip() if context.args else None
    reason = reason or None
    conn = get_conn()
    already = conn.execute(
        "SELECT id FROM blocked_stickers WHERE sticker_unique_id = ?", (sticker.file_unique_id,)
    ).fetchone()
    pack_already = (
        conn.execute(
            "SELECT id FROM blocked_sticker_packs WHERE sticker_set_name = ?", (sticker.set_name,)
        ).fetchone()
        if sticker.set_name else None
    )
    conn.close()
    if already or pack_already:
        await safe_reply(update, context, f"{pemoji('error')} That sticker is already blocked.", parse_mode="HTML")
        return

    set_pending(actor.id, "dblock_choice", 1, {
        "sticker_unique_id": sticker.file_unique_id,
        "sticker_file_id": sticker.file_id,
        "sticker_set_name": sticker.set_name,
        "reason": reason,
        "command_message_id": msg.message_id,
        "sticker_message_id": replied.message_id,
        "chat_id": msg.chat_id,
    })
    pack_label = html_escape(sticker.set_name) if sticker.set_name else "No sticker pack detected"
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("Sticker", callback_data=f"dblock_single_{actor.id}", style="primary")],
        [InlineKeyboardButton("Pack", callback_data=f"dblock_pack_{actor.id}", style="danger")],
    ])
    await safe_reply(update, context, 
        f"{pemoji('lock')} <b>What do you want to block?</b>\n\n"
        f"<b>Pack:</b> {pack_label}",
        parse_mode="HTML",
        reply_markup=keyboard,
    )


async def handle_dblock_choice(query, context, data):
    actor = query.from_user
    if not await is_authorized(context, actor.id, "can_delete_messages"):
        await query.answer("You are not authorized for this action.", show_alert=True)
        return
    parts = data.split("_")
    if len(parts) != 3 or parts[1] not in {"single", "pack"}:
        await query.answer("This block choice is invalid.", show_alert=True)
        return
    pending = get_pending(actor.id)
    if not pending or pending["action"] != "dblock_choice":
        await query.answer("This block choice has expired.", show_alert=True)
        return
    info = pending["data"]
    action = parts[1]
    conn = get_conn()
    try:
        if action == "pack":
            pack_name = info.get("sticker_set_name")
            if not pack_name:
                conn.close()
                await query.answer("This sticker has no identifiable pack.", show_alert=True)
                return
            conn.execute(
                "INSERT INTO blocked_sticker_packs (sticker_set_name, blocked_by, reason, created_at) VALUES (?, ?, ?, ?)",
                (pack_name, actor.id, info.get("reason"), now_iso()),
            )
            result = "Sticker pack blocked."
        else:
            conn.execute(
                "INSERT INTO blocked_stickers (sticker_unique_id, sticker_file_id, sticker_set_name, blocked_by, reason, created_at) VALUES (?, ?, ?, ?, ?, ?)",
                (info["sticker_unique_id"], info["sticker_file_id"], info.get("sticker_set_name"), actor.id, info.get("reason"), now_iso()),
            )
            result = "Sticker blocked."
        conn.commit()
    except Exception as e:
        conn.close()
        await query.answer("Could not save this block.", show_alert=True)
        await notify_devs(context, "handle_dblock_choice: save", e)
        return
    conn.close()
    clear_pending(actor.id)
    for message_id in (info.get("sticker_message_id"), info.get("command_message_id")):
        if message_id:
            try:
                await context.bot.delete_message(info.get("chat_id", GROUP_ID), message_id)
            except Exception:
                pass
    await query.answer()
    try:
        await query.edit_message_text(f"{pemoji('denied')} {result}", parse_mode="HTML")
    except Exception:
        pass

# ---------------------------------------------------------------------------
# /unblocksticker — reply to a (re-sent) copy of a blocked sticker, or give
# the index number shown by /blockedstickers, to remove it from the list.
# ---------------------------------------------------------------------------
async def cmd_unblocksticker(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_delete_messages", update=update):
        await deny_not_authorized(update, context)
        return
    await _delete_admin_command_message(context, update)

    msg = update.message
    replied = msg.reply_to_message

    conn = get_conn()

    if replied and replied.sticker:
        row = conn.execute(
            "SELECT id FROM blocked_stickers WHERE sticker_unique_id = ?",
            (replied.sticker.file_unique_id,),
        ).fetchone()
        if not row:
            conn.close()
            await safe_reply(update, context, f"{pemoji('error')} That sticker isn't on the block list.", parse_mode="HTML")
            return
        conn.execute("DELETE FROM blocked_stickers WHERE id = ?", (row["id"],))
        conn.commit()
        conn.close()
        await safe_reply(update, context, f"{pemoji('approve')} Sticker unblocked.", parse_mode="HTML")
        return

    arg = (context.args[0] if context.args else "").strip()
    if not arg.isdigit():
        conn.close()
        await safe_reply(update, context, 
            f"{pemoji('usage')} Usage:\n"
            "• Reply to a copy of the sticker with <code>/unblocksticker</code>\n"
            "• Or <code>/unblocksticker &lt;number&gt;</code> using the number from /blockedstickers",
            parse_mode="HTML",
        )
        return

    index = int(arg)
    rows = conn.execute("SELECT id FROM blocked_stickers ORDER BY created_at ASC").fetchall()
    if index < 1 or index > len(rows):
        conn.close()
        await safe_reply(update, context, 
            f"{pemoji('error')} No blocked sticker at #{index}. Check /blockedstickers for valid numbers.",
            parse_mode="HTML",
        )
        return

    conn.execute("DELETE FROM blocked_stickers WHERE id = ?", (rows[index - 1]["id"],))
    conn.commit()
    conn.close()
    await safe_reply(update, context, f"{pemoji('approve')} Sticker #{index} unblocked.", parse_mode="HTML")


# ---------------------------------------------------------------------------
# /blockedstickers — DM-only review list. Resends each blocked sticker (from
# its stored file_id) with a caption, since the id strings alone are
# meaningless for visually telling stickers apart.
# ---------------------------------------------------------------------------
BLOCKED_STICKERS_LIST_CAP = 20


async def cmd_blockedstickers(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_delete_messages", update=update):
        await deny_not_authorized(update, context)
        return

    conn = get_conn()
    rows = conn.execute(
        "SELECT sticker_file_id, sticker_set_name, blocked_by, reason, created_at "
        "FROM blocked_stickers ORDER BY created_at ASC"
    ).fetchall()
    conn.close()

    if not rows:
        await safe_reply(update, context, f"{pemoji('denied')} No stickers are currently blocked.", parse_mode="HTML")
        return

    shown = rows[-BLOCKED_STICKERS_LIST_CAP:]
    start_index = len(rows) - len(shown) + 1

    await safe_reply(update, context, 
        f"{pemoji('denied')} <b>{len(rows)} blocked sticker(s)</b>"
        + (f" — showing the {len(shown)} most recent" if len(rows) > BLOCKED_STICKERS_LIST_CAP else "")
        + f".\nUse <code>/unblocksticker &lt;number&gt;</code> to remove one.",
        parse_mode="HTML",
    )

    for i, row in enumerate(shown, start=start_index):
        blocked_name = _known_display_name(row["blocked_by"]) if row["blocked_by"] else "an admin"
        caption = (
            f"#{i} — from {html_escape(row['sticker_set_name'] or 'an unknown pack')}\n"
            f"Blocked by {blocked_name}"
            + (f"\nReason: {html_escape(row['reason'])}" if row["reason"] else "")
        )
        try:
            await context.bot.send_sticker(update.effective_chat.id, sticker=row["sticker_file_id"])
            await context.bot.send_message(update.effective_chat.id, caption, parse_mode="HTML")
        except Exception as e:
            await notify_devs(context, "cmd_blockedstickers: send_sticker", e)


# ---------------------------------------------------------------------------
# /del — delete a message with no punishment attached, just an in-group
# callout to the sender explaining why (reason is optional).
# ---------------------------------------------------------------------------
async def cmd_del(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_delete_messages", update=update):
        await deny_not_authorized(update, context)
        return

    msg = update.message
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        await safe_reply(update, context, 
            f"{pemoji('usage')} Reply to the message you want deleted with <code>/del &lt;reason&gt;</code> "
            "(reason is optional).",
            parse_mode="HTML",
        )
        return

    target = msg.reply_to_message.from_user
    target_id = target.id
    reason = " ".join(context.args).strip() if context.args else None
    reason = reason or None

    target_mention = f"@{target.username}" if target.username else html_escape(target.full_name)

    # Delete the offending message and the admin's own command message.
    for message_to_delete in (msg.reply_to_message, msg):
        try:
            await context.bot.delete_message(GROUP_ID, message_to_delete.message_id)
        except Exception as e:
            await notify_devs(context, "cmd_del: delete_message", e)

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'delete', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, target_id, reason, actor.id, now_iso()),
    )
    conn.commit()
    conn.close()

    announcement = f"{pemoji('delete')} {target_mention}, your message was deleted."
    announcement += f"\nReason: {html_escape(reason) if reason else 'No reason given'}"

    try:
        await context.bot.send_message(GROUP_ID, announcement, parse_mode="HTML")
    except Exception as e:
        await notify_devs(context, "cmd_del: announcement", e)


# ---------------------------------------------------------------------------
# /purge — bulk-delete recent messages (admin-only, group-only)
# ---------------------------------------------------------------------------
PURGE_MAX_MESSAGES = 500  # hard ceiling per invocation, to keep this sane
_PURGE_BATCH_SIZE = 100   # Bot API's deleteMessages caps out at 100 ids/call


async def _scheduled_delete_job(context: ContextTypes.DEFAULT_TYPE):
    chat_id, message_id = context.job.data["chat_id"], context.job.data["message_id"]
    try:
        await context.bot.delete_message(chat_id, message_id)
    except Exception as e:
        # "message to delete not found" just means it's already gone (a user
        # or another admin deleted it first, or it expired) — routine, not
        # worth a dev alert. Anything else (most commonly: the bot lost its
        # "Delete messages" admin right) means auto-delete has silently
        # stopped working, so that DOES get flagged.
        if "message to delete not found" not in str(e).lower():
            await notify_devs(context, "_scheduled_delete_job: delete_message", e)


async def cmd_purge(update: Update, context: ContextTypes.DEFAULT_TYPE):
    actor = update.effective_user
    if not await is_authorized(context, actor.id, "can_delete_messages", update=update):
        await deny_not_authorized(update, context)
        return

    msg = update.message
    reply = msg.reply_to_message

    if reply:
        # Delete everything from the replied-to message through the /purge
        # command itself, inclusive.
        start_id, end_id = reply.message_id, msg.message_id
        if end_id - start_id + 1 > PURGE_MAX_MESSAGES:
            await safe_reply(update, context, 
                f"{pemoji('error')} That's too many messages at once (max {PURGE_MAX_MESSAGES}). "
                "Reply closer to the range you want.",
                parse_mode="HTML",
            )
            return
        message_ids = list(range(start_id, end_id + 1))
    else:
        arg = (context.args[0] if context.args else "").strip()
        if not arg.isdigit() or int(arg) < 1:
            await safe_reply(update, context, 
                f"{pemoji('usage')} Usage:\n"
                "• Reply to a message with <code>/purge</code> to delete from there up to now\n"
                "• Or <code>/purge &lt;count&gt;</code> to delete the last N messages\n\n"
                f"Example: <code>/purge 50</code> (max {PURGE_MAX_MESSAGES} per run)",
                parse_mode="HTML",
            )
            return
        count = min(int(arg), PURGE_MAX_MESSAGES)
        # message_id - count .. message_id - 1 are the count messages before
        # this command, plus the command message itself.
        message_ids = list(range(msg.message_id - count, msg.message_id + 1))

    deleted = 0
    failed = 0
    for i in range(0, len(message_ids), _PURGE_BATCH_SIZE):
        batch = message_ids[i:i + _PURGE_BATCH_SIZE]
        try:
            await context.bot.delete_messages(GROUP_ID, batch)
            deleted += len(batch)
        except Exception:
            # Bulk delete failed (mixed old/already-gone messages, etc.) —
            # fall back to one at a time so a few bad ids don't sink the
            # whole batch. Telegram only lets bots delete others' messages
            # if they're under 48h old.
            for message_id in batch:
                try:
                    await context.bot.delete_message(GROUP_ID, message_id)
                    deleted += 1
                except Exception:
                    failed += 1
                await asyncio.sleep(0.05)  # stay well under flood limits

    conn = get_conn()
    conn.execute(
        "INSERT INTO moderation_actions (chat_id, chat_title, user_id, action, reason, admin_id, created_at, status) "
        "VALUES (?, ?, ?, 'purge', ?, ?, ?, 'active')",
        (GROUP_ID, GROUP_NAME, actor.id, f"{deleted} messages deleted", actor.id, now_iso()),
    )
    conn.commit()
    conn.close()

    summary = f"{pemoji('purge')} Purged {deleted} message{'s' if deleted != 1 else ''}."
    if failed:
        summary += f" ({failed} couldn't be deleted — likely older than 48h or already gone.)"
    status_msg = await context.bot.send_message(GROUP_ID, summary, parse_mode="HTML")
    if context.job_queue is not None:
        context.job_queue.run_once(
            _scheduled_delete_job,
            when=8,
            data={"chat_id": GROUP_ID, "message_id": status_msg.message_id},
        )


# ---------------------------------------------------------------------------
# /report — Rose-bot-style "ping every admin right now". Any group member
# can use it (this is how members reach admins, not an admin-only tool).
# Admins are tagged via invisible tg://user? links — each one gets a real
# notification ping, but no @usernames actually show up in the message.
# The literal text "@admin" / "@admins" triggers the same thing, matching
# the behavior people expect from Rose.
# ---------------------------------------------------------------------------
ADMIN_CALL_COOLDOWN_SECONDS = 60
_LAST_ADMIN_CALL = {}  # user_id -> monotonic time of their last call

# Admins in this set still have full mod powers (mute/ban/warn/etc.), they
# just never get pinged by "@admins" or /report in the group.
ADMIN_CALL_EXCLUDE_IDS = {5114476882, 8135140374}


async def _hidden_admin_mentions(context: ContextTypes.DEFAULT_TYPE) -> str:
    """One invisible HTML mention per pingable admin — the fixed ADMIN_IDS
    list plus current Telegram admins with restrict rights, minus
    ADMIN_CALL_EXCLUDE_IDS. Each renders as a zero-width character —
    nothing visible shows up, but Telegram still delivers a real
    notification to that admin."""
    pingable = (await get_notifiable_admins(context)) - ADMIN_CALL_EXCLUDE_IDS
    return "".join(f'<a href="tg://user?id={admin_id}">\u2060</a>' for admin_id in pingable)


async def _do_call_admins(update: Update, context: ContextTypes.DEFAULT_TYPE, reason: str):
    user = update.effective_user
    await track_user(user)

    now = time.monotonic()
    last = _LAST_ADMIN_CALL.get(user.id)
    if last is not None and (now - last) < ADMIN_CALL_COOLDOWN_SECONDS:
        wait = int(ADMIN_CALL_COOLDOWN_SECONDS - (now - last))
        await safe_reply(update, context, 
            f"{pemoji('error')} Please wait {wait}s before calling admins again.",
            parse_mode="HTML",
        )
        return
    _LAST_ADMIN_CALL[user.id] = now

    caller = f"@{user.username}" if user.username else html_escape(user.full_name)
    text = f"{pemoji('report')} {await _hidden_admin_mentions(context)}<b>Admins needed!</b>\nCalled by {caller}"
    if reason:
        text += f"\nReason: {html_escape(reason)}"

    await safe_reply(update, context, text, parse_mode="HTML")


async def cmd_call_admins(update: Update, context: ContextTypes.DEFAULT_TYPE):
    reason = " ".join(context.args).strip() if context.args else ""
    await _do_call_admins(update, context, reason)


_ADMIN_CALL_TEXT_PATTERN = re.compile(r'^@admins?\b\s*(.*)$', re.IGNORECASE | re.DOTALL)


async def handle_admin_call_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Catches the literal '@admin' / '@admins' typed as a plain message
    (not a slash command), so context.args is never auto-populated — the
    reason has to be pulled out of the raw text by hand here instead."""
    msg = update.effective_message
    if not msg or not msg.text:
        return
    match = _ADMIN_CALL_TEXT_PATTERN.match(msg.text.strip())
    if not match:
        return
    reason = (match.group(1) or "").strip()
    await _do_call_admins(update, context, reason)


# ---------------------------------------------------------------------------
# Alt-prefix aliases — lets admins trigger mod commands with ".", "!" or "*"
# in addition to the normal "/", e.g. ".mute", "!ban", "*warn @user spam".
# Telegram only auto-parses "/" as a bot command, so these are matched by
# hand via a regex MessageHandler and then dispatched into the same cmd_*
# functions above (context.args is filled in exactly like CommandHandler
# would fill it, so all the existing logic — perms, DB writes, DMs — is
# reused unchanged).
