async def handle_appeal_action(query, context, data):
    actor = query.from_user
    if not await is_authorized(context, actor.id, "can_restrict_members"):
        await query.answer("You are not authorized for this action.", show_alert=True)
        return

    parts = data.split("_")
    act, appeal_id, target_id = parts[1], parts[2], int(parts[3])

    conn = get_conn()
    appeal = conn.execute("SELECT status FROM appeals WHERE id = ?", (appeal_id,)).fetchone()
    if not appeal or appeal["status"] != "pending":
        conn.close()
        await query.answer(
            "Action has already been taken on this appeal by another admin.", show_alert=True
        )
        await cleanup_admin_messages(context, f"appeal_{appeal_id}")
        return

    key = f"appeal_{appeal_id}"

    if act == "approve":
        # Figure out whether this was a mute or a ban, so the DM to the
        # user says the right thing ("unmuted" vs "unbanned").
        action_row = conn.execute(
            "SELECT action FROM moderation_actions "
            "WHERE chat_id = ? AND user_id = ? AND action IN ('mute','ban') AND status = 'active' "
            "ORDER BY created_at DESC LIMIT 1",
            (GROUP_ID, target_id),
        ).fetchone()
        action_type = action_row["action"] if action_row else None

        try:
            await context.bot.unban_chat_member(GROUP_ID, target_id, only_if_banned=True)
            await context.bot.restrict_chat_member(GROUP_ID, target_id, permissions=FULL_PERMISSIONS)
            conn.execute("UPDATE appeals SET status = 'approved' WHERE id = ?", (appeal_id,))
            conn.execute(
                "UPDATE moderation_actions SET status = 'lifted' "
                "WHERE chat_id = ? AND user_id = ? AND action IN ('mute','ban') AND status = 'active'",
                (GROUP_ID, target_id),
            )
            conn.commit()
            await query.answer("Appeal approved. User unmuted/unbanned.")

            verb = {"ban": "unbanned", "mute": "unmuted"}.get(action_type, "unbanned/unmuted")
            try:
                await context.bot.send_message(
                    target_id,
                    f"{pemoji('approve')} Your appeal has been approved. You're now {verb} in "
                    f"<b>{html_escape(GROUP_NAME)}</b>.",
                    parse_mode="HTML",
                    reply_markup=InlineKeyboardMarkup(
                        [[InlineKeyboardButton("Join the group", url=GROUP_LINK, style="success")]]
                    ),
                )
            except Exception as e:
                logger.warning(f"handle_appeal_action(approve): couldn't DM user {target_id}: {e}")
        except Exception as e:
            await notify_devs(context, "handle_appeal_action: unban/unmute", e)
            await query.answer(f"Failed to unban/unmute: {_short_for_alert(friendly_error(e))}", show_alert=True)
            conn.close()
            return
    elif act == "reject":
        # Don't finalize yet — ask the admin for a reason first, with a
        # Skip button for rejecting without one.
        await query.answer()
        conn.close()
        prompt = await context.bot.send_message(
            actor.id,
            f"{pemoji('reject')} Send the rejection reason as a message, or tap Skip to reject "
            "without one.\n\nSend /cancel to abort.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(
                [[InlineKeyboardButton(
                    "Skip", callback_data=f"appeal_rejectskip_{appeal_id}_{target_id}", style="danger"
                )]]
            ),
        )
        set_pending(actor.id, "appeal_reject_reason", 1, {
            "appeal_id": appeal_id, "target_id": target_id, "notif_key": key,
            "prompt_message_id": prompt.message_id,
        })
        return
    elif act == "rejectskip":
        conn.close()
        clear_pending(actor.id)
        ok = await _finalize_appeal_rejection(context, appeal_id, target_id, None, key)
        try:
            await query.message.delete()
        except Exception:
            pass
        await query.answer("Appeal rejected." if ok else "Already handled by another admin.")
        return
    else:
        conn.close()
        return

    conn.close()
    await cleanup_admin_messages(context, key)


async def _finalize_appeal_rejection(context: ContextTypes.DEFAULT_TYPE, appeal_id, target_id, reason, notif_key):
    """Marks an appeal rejected (with or without a reason), DMs the user,
    and cleans up the admin notification cards. Returns False if the
    appeal was already resolved by another admin in the meantime."""
    conn = get_conn()
    row = conn.execute("SELECT status FROM appeals WHERE id = ?", (appeal_id,)).fetchone()
    if not row or row["status"] != "pending":
        conn.close()
        return False

    conn.execute(
        "UPDATE appeals SET status = 'rejected', rejection_reason = ? WHERE id = ?",
        (reason, appeal_id),
    )
    conn.commit()
    conn.close()

    text = f"{pemoji('reject')} Your appeal in <b>{html_escape(GROUP_NAME)}</b> has been rejected."
    if reason:
        text += f"\nReason: {html_escape(reason)}"
    try:
        await context.bot.send_message(target_id, text, parse_mode="HTML")
    except Exception as e:
        logger.warning(f"_finalize_appeal_rejection: couldn't DM user {target_id}: {e}")

    await cleanup_admin_messages(context, notif_key)
    return True


# ---------------------------------------------------------------------------
# Health Server
# ---------------------------------------------------------------------------
class _HealthHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"OK")


def start_health_server_if_needed():
    port = os.environ.get("PORT")
    if not port:
        return
    server = HTTPServer(("0.0.0.0", int(port)), _HealthHandler)
    threading.Thread(target=server.serve_forever, daemon=True).start()


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    init_db()
    global _APPROVED_USERS_CACHE
    conn = get_conn()
    _APPROVED_USERS_CACHE = {row["user_id"] for row in conn.execute("SELECT user_id FROM approved_users").fetchall()}
    conn.close()
    start_health_server_if_needed()

    # Restore anti-spam config from the last time it was set via /spam,
    # if any — otherwise the defaults from _SPAM_CONFIG above stand.
    saved_limit = get_setting("spam_limit")
    if saved_limit and saved_limit.isdigit():
        _SPAM_CONFIG["limit"] = int(saved_limit)
    saved_enabled = get_setting("spam_enabled")
    if saved_enabled is not None:
        _SPAM_CONFIG["enabled"] = saved_enabled == "1"
    saved_action = get_setting("spam_action")
    if saved_action in {"mute", "warn"}:
        _SPAM_CONFIG["action"] = saved_action
    saved_mute_seconds = get_setting("spam_mute_seconds")
    if saved_mute_seconds and saved_mute_seconds.isdigit() and int(saved_mute_seconds) >= 1:
        _SPAM_CONFIG["mute_seconds"] = int(saved_mute_seconds)
    global _AUTO_APPROVE_JOIN_REQUESTS
    _AUTO_APPROVE_JOIN_REQUESTS = get_setting("autoapprove_join_requests", "0") == "1"

    app = (
        Application.builder()
        .token(BOT_TOKEN)
        .post_init(enforce_group_default_permissions)
        .build()
    )
    if app.job_queue is not None:
        app.job_queue.run_repeating(cleanup_old_records_job, interval=timedelta(hours=24), first=60)

    private = filters.ChatType.PRIVATE

    # Blocked-user gate — group=-1 so it runs before every other handler
    # below and can short-circuit a blocked user's DM entirely.
    app.add_handler(MessageHandler(private & filters.ALL, blocked_gate), group=-1)
    app.add_handler(CallbackQueryHandler(blocked_gate), group=-1)

